@Composable
fun AdminCustomBannerView(settingsState: com.example.data.AdminSettingsEntity, themeColors: VisualThemePalette) {
    var isVisible by remember(settingsState.bannerContent, settingsState.bannerEnabled) { mutableStateOf(true) }
    
    if (settingsState.bannerDurationSeconds > 0) {
        LaunchedEffect(settingsState.bannerContent, settingsState.bannerEnabled) {
            kotlinx.coroutines.delay(settingsState.bannerDurationSeconds * 1000L)
            isVisible = false
        }
    }

    if (!isVisible || !settingsState.bannerEnabled) return

    val imageBitmap = remember(settingsState.bannerBase64) {
        if (!settingsState.bannerBase64.isNullOrEmpty()) {
            try {
                val bytes = android.util.Base64.decode(settingsState.bannerBase64, android.util.Base64.DEFAULT)
                android.graphics.BitmapFactory.decodeByteArray(bytes, 0, bytes.size)?.asImageBitmap()
            } catch(e: Exception) { null }
        } else null
    }

    var startAnimation by remember { mutableStateOf(false) }
    LaunchedEffect(isVisible) {
        if (isVisible) {
            startAnimation = true
        }
    }

    val style = settingsState.bannerDisplayStyle ?: "SLIDE"

    // Animations corresponding to display styles
    val slideOffset by androidx.compose.animation.core.animateDpAsState(
        targetValue = if (startAnimation && style == "SLIDE") 0.dp else if (style == "SLIDE") (-300).dp else 0.dp,
        animationSpec = androidx.compose.animation.core.tween(800)
    )

    val fadeAlpha by androidx.compose.animation.core.animateFloatAsState(
        targetValue = if (startAnimation) 1f else 0f,
        animationSpec = androidx.compose.animation.core.tween(1000)
    )

    val infiniteTransition = androidx.compose.animation.core.rememberInfiniteTransition()
    val blinkAlpha by infiniteTransition.animateFloat(
        initialValue = 1f,
        targetValue = 0.3f,
        animationSpec = androidx.compose.animation.core.infiniteRepeatable(
            animation = androidx.compose.animation.core.tween(800, easing = androidx.compose.animation.core.LinearEasing),
            repeatMode = androidx.compose.animation.core.RepeatMode.Reverse
        )
    )

    val scrollOffset by infiniteTransition.animateFloat(
        initialValue = 50f,
        targetValue = -50f,
        animationSpec = androidx.compose.animation.core.infiniteRepeatable(
            animation = androidx.compose.animation.core.tween(4000, easing = androidx.compose.animation.core.LinearEasing),
            repeatMode = androidx.compose.animation.core.RepeatMode.Reverse
        )
    )

    val appliedModifier = Modifier
        .fillMaxWidth()
        .padding(vertical = 4.dp)
        .let { modifier ->
            when (style) {
                "SLIDE" -> modifier.offset(x = slideOffset)
                "FADE" -> modifier.alpha(fadeAlpha)
                "BLINK" -> modifier.alpha(blinkAlpha)
                "SCROLL" -> modifier.offset(x = scrollOffset.dp)
                else -> modifier
            }
        }

    Card(
        modifier = appliedModifier,
        shape = RoundedCornerShape(12.dp),
        border = BorderStroke(1.5.dp, themeColors.accent.copy(alpha = 0.6f)),
        colors = CardDefaults.cardColors(containerColor = themeColors.surface),
        elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
    ) {
        Box(modifier = Modifier.fillMaxWidth()) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(12.dp)
            ) {
                // Header row with title and type icon
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        val icon = when (settingsState.bannerType) {
                            "IMAGE" -> "🖼️"
                            "VIDEO" -> "📹"
                            else -> "📢"
                        }
                        Text(icon, fontSize = 16.sp)
                        Spacer(modifier = Modifier.width(6.dp))
                        Text(
                            text = "إعلان رسمي من إدارة المنصة",
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = themeColors.accent
                        )
                    }
                    
                    // Dismiss button
                    IconButton(
                        onClick = { isVisible = false },
                        modifier = Modifier.size(24.dp)
                    ) {
                        Text("✕", fontSize = 12.sp, color = Color.White.copy(alpha = 0.6f))
                    }
                }
                
                Spacer(modifier = Modifier.height(8.dp))

                when (settingsState.bannerType) {
                    "IMAGE" -> {
                        if (imageBitmap != null) {
                            Image(
                                bitmap = imageBitmap,
                                contentDescription = "إعلان بنر",
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(130.dp)
                                    .clip(RoundedCornerShape(8.dp)),
                                contentScale = androidx.compose.ui.layout.ContentScale.Crop
                            )
                        } else {
                            // Load from remote URL or show decorative placeholder
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(130.dp)
                                    .background(Color.DarkGray, RoundedCornerShape(8.dp)),
                                contentAlignment = Alignment.Center
                            ) {
                                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                    Text("📢 إعلان مرئي", fontSize = 16.sp, color = themeColors.accent)
                                    Spacer(modifier = Modifier.height(4.dp))
                                    Text(settingsState.bannerContent, fontSize = 11.sp, color = Color.White, textAlign = TextAlign.Center, modifier = Modifier.padding(horizontal = 8.dp))
                                }
                            }
                        }
                    }
                    "VIDEO" -> {
                        // Simulated high-fidelity Video Player card as requested
                        var isPlaying by remember { mutableStateOf(true) }
                        var simulatedProgress by remember { mutableStateOf(0.4f) }
                        
                        LaunchedEffect(isPlaying) {
                            if (isPlaying) {
                                while (true) {
                                    kotlinx.coroutines.delay(1000L)
                                    simulatedProgress = (simulatedProgress + 0.05f)
                                    if (simulatedProgress >= 1.0f) simulatedProgress = 0.0f
                                }
                            }
                        }

                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(150.dp)
                                .clip(RoundedCornerShape(8.dp))
                                .background(Color.Black),
                            contentAlignment = Alignment.Center
                        ) {
                            if (imageBitmap != null) {
                                Image(
                                    bitmap = imageBitmap,
                                    contentDescription = "فيديو البنر",
                                    modifier = Modifier.fillMaxSize().alpha(0.6f),
                                    contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                )
                            } else {
                                Box(modifier = Modifier.fillMaxSize().background(Color(0xFF0F172A)).alpha(0.5f))
                            }
                            
                            // REC Indicator
                            Row(
                                modifier = Modifier
                                    .align(Alignment.TopStart)
                                    .padding(8.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(8.dp)
                                        .background(Color.Red, CircleShape)
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                Text("LIVE", fontSize = 9.sp, color = Color.Red, fontWeight = FontWeight.Bold)
                            }

                            // Play/Pause Overlay Button
                            IconButton(
                                onClick = { isPlaying = !isPlaying },
                                modifier = Modifier
                                    .size(44.dp)
                                    .background(Color.Black.copy(alpha = 0.6f), CircleShape)
                            ) {
                                Text(if (isPlaying) "⏸️" else "▶️", fontSize = 18.sp)
                            }

                            // Video Controls Overlay at Bottom
                            Column(
                                modifier = Modifier
                                    .align(Alignment.BottomCenter)
                                    .fillMaxWidth()
                                    .background(Color.Black.copy(alpha = 0.6f))
                                    .padding(horizontal = 8.dp, vertical = 4.dp)
                            ) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = if (settingsState.bannerContent.length > 30) settingsState.bannerContent.take(30) + "..." else settingsState.bannerContent,
                                        fontSize = 10.sp,
                                        color = Color.White
                                    )
                                    Text("00:0${(simulatedProgress * 15).toInt()} / 00:15", fontSize = 9.sp, color = Color.LightGray)
                                }
                                Spacer(modifier = Modifier.height(4.dp))
                                // Custom progress bar
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(3.dp)
                                        .background(Color.Gray)
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .fillMaxWidth(simulatedProgress)
                                            .fillMaxHeight()
                                            .background(themeColors.accent)
                                    )
                                }
                            }
                        }
                    }
                    else -> {
                        // Text Banner
                        val welcomeMsg = "أهلاً بكم في دليل خدمات اليمن! المنصة الأولى لربط مقدمي الخدمات والمهنيين والمراكز التجارية مع المستخدمين، وانتظروا الإضافات القادمة! ✨"
                        val displayText = if (settingsState.bannerContent.contains("خصومات") || settingsState.bannerContent.contains("الصيانة الكهربائية") || settingsState.bannerContent.isBlank()) {
                            welcomeMsg
                        } else {
                            settingsState.bannerContent
                        }
                        Card(
                            colors = CardDefaults.cardColors(containerColor = themeColors.accent.copy(alpha = 0.15f)),
                            border = BorderStroke(1.dp, themeColors.accent.copy(alpha = 0.4f)),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Row(
                                modifier = Modifier.padding(12.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text("📢", fontSize = 24.sp)
                                Spacer(modifier = Modifier.width(10.dp))
                                Text(
                                    text = displayText,
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Medium,
                                    color = Color.White,
                                    lineHeight = 18.sp
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

// ------ Main Category and Service Directory Browser Layout ------
@Composable
fun ServicesBrowserLayout(
    viewModel: MainViewModel,
    themeColors: VisualThemePalette,
    activeSectionIdForCreation: String,
    onActiveSectionIdForCreationChange: (String) -> Unit,
    preselectedRegistrationType: String,
    onPreselectedRegistrationTypeChange: (String) -> Unit,
    onChatOpen: (String) -> Unit
) {
    val categories by viewModel.categories.collectAsState()
    val filteredProviders by viewModel.filteredProviders.collectAsState()
    val selectedCategory by viewModel.selectedCategoryId.collectAsState()
    val searchQuery by viewModel.searchQuery.collectAsState()
    val isVipOnly by viewModel.filterVipOnly.collectAsState()
    val isAvailableOnly by viewModel.filterAvailableOnly.collectAsState()
    val citiesList by viewModel.cities.collectAsState()
    val activeCityId by viewModel.filterCityId.collectAsState()
    val radiusKm by viewModel.maxKmRadius.collectAsState()
    val neighborFilter by viewModel.filterNeighborhoodName.collectAsState()
    val phoneOrNameFilter by viewModel.phoneOrNameFilter.collectAsState()
    val bannersList by viewModel.banners.collectAsState()
    val settingsState by viewModel.settings.collectAsState()

    val currentUserIdState by viewModel.currentUserId.collectAsState()
    val currentUserPhoneState by viewModel.currentUserPhone.collectAsState()
    val bookings by viewModel.bookings.collectAsState()
    val myBookings = remember(bookings, currentUserPhoneState) {
        bookings.filter { it.customerPhone.trim() == currentUserPhoneState.trim() && currentUserPhoneState.isNotEmpty() }
    }
    var showGuestRegisterDialogForBooking by remember { mutableStateOf(false) }
    val context = androidx.compose.ui.platform.LocalContext.current

    // Payment-related state collections and dialog states
    val paymentWallets by viewModel.paymentWallets.collectAsState()
    val paymentsList by viewModel.payments.collectAsState()

    var payingBookingObj by remember { mutableStateOf<BookingEntity?>(null) }
    var selectedUserWalletObj by remember { mutableStateOf<PaymentWalletEntity?>(null) }
    var userTransferIdInput by remember { mutableStateOf("") }
    var userTransferAccountNameInput by remember { mutableStateOf("") }
    var userTransferPhotoInput by remember { mutableStateOf("") }

    var showFiltersPanel by remember { mutableStateOf(false) }

    // --- STORES & REAL ESTATE COMPONENT STATES ---
    val parsedSections = remember(settingsState.dynamicSectionsData) {
        com.example.data.DynamicSection.parseDynamicSections(settingsState.dynamicSectionsData)
    }
    val activeTabs = remember(parsedSections, settingsState.isStoresEnabled, settingsState.isPropertiesEnabled) {
        val list = mutableListOf("الرئيسية")
        parsedSections.filter { it.isEnabled }.forEach { sec ->
            if ((sec.id == "stores" || sec.type == "store") && !settingsState.isStoresEnabled) return@forEach
            if ((sec.id == "properties" || sec.type == "property") && !settingsState.isPropertiesEnabled) return@forEach
            list.add(sec.name)
        }
        list.add("المفضلة")
        list.toList()
    }
    var activeTabName by remember(activeTabs) { mutableStateOf(activeTabs.firstOrNull() ?: "الرئيسية") }
    var providersLimit by remember { mutableStateOf(10) }

    var selectedStoreForDetails by remember { mutableStateOf<com.example.data.StoreEntity?>(null) }
    var selectedPropertyForDetails by remember { mutableStateOf<com.example.data.PropertyEntity?>(null) }
    var showStoreCreateDialog by remember { mutableStateOf(false) }
    var showPropertyCreateDialog by remember { mutableStateOf(false) }
    var productToOrderElectronic by remember { mutableStateOf<com.example.data.ProductEntity?>(null) }

    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .padding(12.dp),
        verticalArrangement = Arrangement.spacedBy(10.dp)
    ) {
        if (settingsState.bannerEnabled && settingsState.bannerLocation == "TOP") {
            item {
                AdminCustomBannerView(settingsState = settingsState, themeColors = themeColors)
            }
        }

        // Horizontal banners list
        if (bannersList.isNotEmpty()) {
            item {
                BannerSliderView(banners = bannersList, themeColors = themeColors) { catTarget ->
                    if (catTarget.isNotEmpty()) viewModel.selectCategory(catTarget)
                }
            }
        }

        // Search Bar Block
        item {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(themeColors.surface, RoundedCornerShape(12.dp))
                    .padding(horizontal = 12.dp, vertical = 4.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Icon(imageVector = Icons.Default.Search, contentDescription = "أيقونة البحث عن الخدمات والمهن", tint = themeColors.textSecondary)
                Spacer(modifier = Modifier.width(8.dp))
                OutlinedTextField(
                    value = searchQuery,
                    onValueChange = { viewModel.updateSearchQuery(it) },
                    placeholder = { Text("ابحث عن سباك، كهربائي، حدة...", fontSize = 13.sp, color = themeColors.textSecondary) },
                    modifier = Modifier
                        .weight(1f)
                        .testTag("search_text_input"),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = Color.Transparent,
                        unfocusedBorderColor = Color.Transparent,
                        focusedTextColor = Color.White,
                        unfocusedTextColor = Color.White
                    ),
                    singleLine = true
                )
                
                if (settingsState.isSpeechSearchEnabled) {
                    IconButton(onClick = {
                        VoiceManager.onHear?.invoke { spokenText ->
                            viewModel.updateSearchQuery(spokenText)
                            viewModel.triggerNotification("🎙️ تم سماع صوتك اليمني: $spokenText")
                        }
                    }) {
                        Text("🎙️", fontSize = 20.sp)
                    }
                }

                IconButton(onClick = { showFiltersPanel = !showFiltersPanel }) {
                    Icon(
                        imageVector = if (showFiltersPanel) Icons.Default.Settings else Icons.Default.List,
                        contentDescription = "الفلاتر",
                        tint = themeColors.accent
                    )
                }
            }
        }

        // ----------------- TAB CHIPS BAR -----------------
        item {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .horizontalScroll(rememberScrollState())
                    .padding(vertical = 4.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                activeTabs.forEach { tabName ->
                    val isSelected = activeTabName == tabName
                    val icon = when (tabName) {
                        "الرئيسية" -> "🛠️"
                        settingsState.storesTabName -> "🏪"
                        settingsState.propertiesTabName -> "🏠"
                        "المفضلة" -> "⭐"
                        else -> "✨"
                    }
                    Box(
                        modifier = Modifier
                            .background(
                                if (isSelected) themeColors.accent else themeColors.surface,
                                RoundedCornerShape(24.dp)
                            )
                            .clickable { activeTabName = tabName }
                            .border(
                                1.dp,
                                if (isSelected) themeColors.accent else themeColors.accent.copy(alpha = 0.2f),
                                RoundedCornerShape(24.dp)
                            )
                            .padding(horizontal = 14.dp, vertical = 8.dp)
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Text(icon, fontSize = 14.sp)
                            Spacer(modifier = Modifier.width(6.dp))
                            val currentLangState by viewModel.currentLanguage.collectAsState()
                            val displayTabName = if (currentLangState == "en") {
                                when (tabName) {
                                    "الرئيسية" -> "Home"
                                    "المفضلة" -> "Favorites"
                                    settingsState.storesTabName -> "Stores"
                                    settingsState.propertiesTabName -> "Properties"
                                    else -> tabName
                                }
                            } else {
                                tabName
                            }
                            Text(
                                text = displayTabName,
                                color = if (isSelected) Color.Black else Color.White,
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                }
            }
        }

        // --- SMART RECOMMENDATIONS ---
        if (activeTabName == "الرئيسية" && (settingsState.isStoresEnabled || settingsState.isPropertiesEnabled)) {
            item {
                SmartRecommendationsSection(
                    viewModel = viewModel,
                    themeColors = themeColors,
                    onStoreClick = { selectedStoreForDetails = it },
                    onPropertyClick = { selectedPropertyForDetails = it }
                )
            }
        }

        // --- CONDITIONAL TABS IN LAZYCOLUMN ---
        val selectedSection = parsedSections.find { it.name == activeTabName && it.isEnabled }
        val isSecTypeEnabled = selectedSection?.let { sec ->
            if (sec.type == "store" && !settingsState.isStoresEnabled) false
            else if (sec.type == "property" && !settingsState.isPropertiesEnabled) false
            else true
        } ?: false
        if (selectedSection != null && isSecTypeEnabled) {
            if (selectedSection.type == "store") {
                item {
                    StoresTabContent(
                        viewModel = viewModel,
                        themeColors = themeColors,
                        onStoreClick = { selectedStoreForDetails = it },
                        onAddStoreClick = {
                            onActiveSectionIdForCreationChange(selectedSection.id)
                            onPreselectedRegistrationTypeChange("STORE")
                            viewModel.navigateTo("REGISTER_FORM")
                        },
                        sectionId = selectedSection.id
                    )
                }
            } else {
                item {
                    PropertiesTabContent(
                        viewModel = viewModel,
                        themeColors = themeColors,
                        onPropertyClick = { selectedPropertyForDetails = it },
                        onAddPropertyClick = {
                            onActiveSectionIdForCreationChange(selectedSection.id)
                            onPreselectedRegistrationTypeChange("PROPERTY")
                            viewModel.navigateTo("REGISTER_FORM")
                        },
                        sectionId = selectedSection.id
                    )
                }
            }
        } else if (activeTabName == "المفضلة") {
            item {
                val currentLangState by viewModel.currentLanguage.collectAsState()
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(16.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    val favTitle = if (currentLangState == "en") "⭐ Favorite Tabs & Stores" else "⭐ التبويبات والمحلات المفضلة"
                    val favDesc = if (currentLangState == "en") "Your personal favorites will be saved here for quick access later." else "سيتم حفظ مفضلاتك الشخصية هنا للوصول السريع إليها لاحقاً."
                    Text(favTitle, fontSize = 14.sp, fontWeight = FontWeight.Bold, color = themeColors.accent)
                    Text(favDesc, fontSize = 11.sp, color = themeColors.textSecondary)
                }
            }
        } else {
            // "الرئيسية" / Standard flow

            // Yemen Cities Tabs / Scroll Selection
            item {
            Column(
                modifier = Modifier
