                                }
                                if (cleanArea.isEmpty()) missing.add("الحي والشارع ومكان السكن (العنوان)")
                                if (cleanService.isEmpty()) missing.add("تفاصيل ومعلومات المشكلة (الوصف)")
                                if (cleanPin.isEmpty()) missing.add("كلمة المرور السرية للحجز")

                                if (missing.isNotEmpty()) {
                                    bookingFormSubmittedOnce = true
                                    bookingFormMissingFields = missing
                                    Toast.makeText(context, "⚠️ هناك حقول مطلوبة أو غير صحيحة!", Toast.LENGTH_LONG).show()
                                } else {
                                    bookingFormSubmittedOnce = false
                                    bookingFormMissingFields = emptyList()
                                    showBookingDialog = false
                                    showBookingConfirmDialog = true
                                }
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = themeColors.accent),
                            modifier = Modifier.weight(1f)
                        ) {
                            Text("تأكيد الحجز", color = Color.Black, fontWeight = FontWeight.Bold, fontSize = 11.sp)
                        }
                        Button(
                            onClick = {
                                bookingFormSubmittedOnce = false
                                bookingFormMissingFields = emptyList()
                                showBookingDialog = false
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color.Gray),
                            modifier = Modifier.weight(1f)
                        ) {
                            Text("إلغاء الحجز", color = Color.White, fontSize = 11.sp)
                        }
                    }
                }
            }
        }
    }

    if (showBookingConfirmDialog) {
        AlertDialog(
            onDismissRequest = { showBookingConfirmDialog = false },
            containerColor = Color(0xFF1E293B),
            title = { Text("📋 هل كافة مدخلات الحجز صحيحة ودقيقة؟", color = Color.White, fontWeight = FontWeight.Bold, fontSize = 15.sp) },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text("📍 تفاصيل طلب الحجز لمراجعتها قبل الإرسال للشبكة:", fontSize = 11.sp, color = themeColors.accent)
                    
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color.Black.copy(alpha = 0.3f), RoundedCornerShape(8.dp))
                            .padding(10.dp),
                        verticalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Text("• الاسم: $customerNameInput", color = Color.White, fontSize = 11.sp)
                        Text("• رقم الهاتف: $customerPhoneInput", color = Color.White, fontSize = 11.sp)
                        Text("• منطقة السكن والحي: $customerAreaInput", color = Color.White, fontSize = 11.sp)
                        Text("• نوع الخدمة: $selectedServiceDropdown", color = Color.Yellow, fontSize = 11.sp)
                        Text("• تاريخ الحجز: $bookingDateInput", color = Color.White, fontSize = 11.sp)
                        Text("• وقت الحجز: $bookingTimeInput", color = Color.White, fontSize = 11.sp)
                        Text("• تفاصيل المشكلة: $customerServiceInput", color = Color.LightGray, fontSize = 11.sp)
                    }

                    Text("• الفني المسؤول: ${provider.name}", color = Color.White, fontSize = 11.sp)
                    Text("• التكاليف المتوقعة: يتم الاتفاق المباشر عليها مع الفني المعتمد بعد المعاينة الميدانية.", color = Color.Green, fontWeight = FontWeight.Bold, fontSize = 11.sp)
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        viewModel.addBooking(
                            name = customerNameInput,
                            phone = customerPhoneInput,
                            area = customerAreaInput,
                            serviceType = "$selectedServiceDropdown - $customerServiceInput",
                            providerId = provider.id,
                            providerName = provider.name,
                            dateString = bookingDateInput,
                            timeString = bookingTimeInput,
                            couponCode = bookingCouponCodeInput,
                            pinCode = bookingPinCodeInput,
                            customBookingId = bookingCustomIdInput,
                            customPassword = bookingPinCodeInput
                        )
                        bookingCouponCodeInput = ""
                        bookingPinCodeInput = ""
                        bookingCustomIdInput = ""
                        showBookingConfirmDialog = false
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF10B981))
                ) {
                    Text("تأكيد وإرسال طلب الحجز", color = Color.White, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                }
            },
            dismissButton = {
                Button(
                    onClick = { showBookingConfirmDialog = false },
                    colors = ButtonDefaults.buttonColors(containerColor = Color.Red)
                ) {
                    Text("تعديل الاستمارة", color = Color.White, fontSize = 11.sp)
                }
            }
        )
    }
}

fun convertGenericUriToBase64(context: android.content.Context, uri: android.net.Uri): String {
    return try {
        val inputStream = context.contentResolver.openInputStream(uri) ?: return ""
        val bytes = inputStream.readBytes()
        inputStream.close()
        android.util.Base64.encodeToString(bytes, android.util.Base64.DEFAULT)
    } catch (e: Exception) { "" }
}

fun convertBitmapToBase64(bitmap: android.graphics.Bitmap): String {
    return try {
        val reqWidth = 220
        val reqHeight = 220
        val scaledBitmap = if (bitmap.width > reqWidth || bitmap.height > reqHeight) {
            val ratio = Math.min(reqWidth.toFloat() / bitmap.width, reqHeight.toFloat() / bitmap.height)
            android.graphics.Bitmap.createScaledBitmap(
                bitmap,
                (bitmap.width * ratio).toInt(),
                (bitmap.height * ratio).toInt(),
                true
            )
        } else {
            bitmap
        }
        val outputStream = java.io.ByteArrayOutputStream()
        scaledBitmap.compress(android.graphics.Bitmap.CompressFormat.JPEG, 55, outputStream)
        val bytes = outputStream.toByteArray()
        if (scaledBitmap != bitmap) {
            scaledBitmap.recycle()
        }
        android.util.Base64.encodeToString(bytes, android.util.Base64.DEFAULT)
    } catch (e: Exception) { "" }
}

fun compressAndResizeImageUri(context: android.content.Context, uri: android.net.Uri, maxDimension: Int = 800, quality: Int = 70): String {
    return try {
        val contentResolver = context.contentResolver
        val inputStreamForBounds = contentResolver.openInputStream(uri) ?: return ""
        val options = android.graphics.BitmapFactory.Options().apply {
            inJustDecodeBounds = true
        }
        android.graphics.BitmapFactory.decodeStream(inputStreamForBounds, null, options)
        inputStreamForBounds.close()

        var inSampleSize = 1
        if (options.outHeight > maxDimension || options.outWidth > maxDimension) {
            val halfHeight = options.outHeight / 2
            val halfWidth = options.outWidth / 2
            while ((halfHeight / inSampleSize) >= maxDimension && (halfWidth / inSampleSize) >= maxDimension) {
                inSampleSize *= 2
            }
        }

        val finalOptions = android.graphics.BitmapFactory.Options().apply {
            inSampleSize = inSampleSize
        }
        val inputStreamForDecode = contentResolver.openInputStream(uri) ?: return ""
        val decodedBitmap = android.graphics.BitmapFactory.decodeStream(inputStreamForDecode, null, finalOptions)
        inputStreamForDecode.close()

        if (decodedBitmap != null) {
            val scaledBitmap = if (decodedBitmap.width > maxDimension || decodedBitmap.height > maxDimension) {
                val ratio = Math.min(maxDimension.toFloat() / decodedBitmap.width, maxDimension.toFloat() / decodedBitmap.height)
                android.graphics.Bitmap.createScaledBitmap(
                    decodedBitmap,
                    (decodedBitmap.width * ratio).toInt(),
                    (decodedBitmap.height * ratio).toInt(),
                    true
                )
            } else {
                decodedBitmap
            }

            val outputStream = java.io.ByteArrayOutputStream()
            scaledBitmap.compress(android.graphics.Bitmap.CompressFormat.JPEG, quality, outputStream)
            val bytes = outputStream.toByteArray()
            if (scaledBitmap != decodedBitmap) {
                scaledBitmap.recycle()
            }
            decodedBitmap.recycle()
            android.util.Base64.encodeToString(bytes, android.util.Base64.NO_WRAP)
        } else ""
    } catch (e: Exception) {
        e.printStackTrace()
        ""
    }
}

@Composable
fun ClientPersonalAccountDashboard(
    viewModel: MainViewModel,
    themeColors: VisualThemePalette,
    context: android.content.Context,
    currentUserName: String,
    currentUserPhone: String,
    currentUserResidence: String,
    currentUserId: String,
    bookings: List<com.example.data.BookingEntity>,
    onShowRegistrationFormsAnyway: () -> Unit
) {
    var showDirectSupportChat by remember { mutableStateOf(false) }
    var showRestoreDialog by remember { mutableStateOf(false) }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp)
            .verticalScroll(rememberScrollState()),
        verticalArrangement = Arrangement.spacedBy(16.dp)
    ) {
        // Main Welcome Banner
        Card(
            colors = CardDefaults.cardColors(containerColor = themeColors.surface),
            shape = RoundedCornerShape(16.dp),
            modifier = Modifier.fillMaxWidth(),
            border = BorderStroke(1.dp, themeColors.accent)
        ) {
            Column(
                modifier = Modifier.padding(16.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Box(
                    modifier = Modifier
                        .size(72.dp)
                        .clip(CircleShape)
                        .background(themeColors.accent.copy(alpha = 0.2f))
                        .border(2.dp, themeColors.accent, CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Text("👤", fontSize = 36.sp)
                }
                Text(
                    text = "مرحباً بك: $currentUserName",
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold,
                    color = Color.White,
                    textAlign = TextAlign.Center
                )
                Text(
                    text = "الحساب الشخصي والتحكم الموحد بالخدمات",
                    fontSize = 12.sp,
                    color = themeColors.textSecondary,
                    textAlign = TextAlign.Center
                )
            }
        }

        // Account Details Card
        Card(
            colors = CardDefaults.cardColors(containerColor = themeColors.surface),
            shape = RoundedCornerShape(12.dp),
            modifier = Modifier.fillMaxWidth()
        ) {
            Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                Text("📋 بيانات الحساب الموثقة:", fontSize = 13.sp, fontWeight = FontWeight.Bold, color = themeColors.accent)
                
                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                    Text("📱 رقم الهاتف اليمني:", fontSize = 11.sp, color = themeColors.textSecondary)
                    Text(currentUserPhone, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color.White)
                }
                Divider(color = Color.Gray.copy(alpha = 0.2f))
                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                    Text("📍 العنوان ومنطقة السكن:", fontSize = 11.sp, color = themeColors.textSecondary)
                    Text(currentUserResidence, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color.White)
                }
                Divider(color = Color.Gray.copy(alpha = 0.2f))
                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                    Text("🆔 معرف الحساب الفريد (ID):", fontSize = 11.sp, color = themeColors.textSecondary)
                    Text(currentUserId, fontSize = 10.sp, fontWeight = FontWeight.Bold, color = themeColors.accent)
                }
            }
        }

        // Live Chat with Support Button
        Button(
            onClick = { showDirectSupportChat = true },
            colors = ButtonDefaults.buttonColors(containerColor = themeColors.primary),
            shape = RoundedCornerShape(12.dp),
            modifier = Modifier.fillMaxWidth().height(48.dp)
        ) {
            Text("💬 محادثة فورية مباشرة مع الإدارة والدعم الفني", color = Color.White, fontSize = 12.sp, fontWeight = FontWeight.Bold)
        }

        // Product & Services Attachments Management Section for Profile
        val stores by viewModel.stores.collectAsState()
        val providers by viewModel.providers.collectAsState()
        val myStore = stores.find { it.ownerId == currentUserPhone || it.phone == currentUserPhone }
        val myProvider = providers.find { it.phone == currentUserPhone }

        var dashboardAttachments by remember(myStore, myProvider) {
            val json = myStore?.productAttachmentsJson ?: myProvider?.productAttachmentsJson ?: ""
            mutableStateOf(com.example.data.ProductAttachment.parseList(json))
        }

        com.example.ui.ProductAttachmentsSection(
            attachments = dashboardAttachments,
            onAttachmentsChanged = { updatedList ->
                dashboardAttachments = updatedList
                val json = com.example.data.ProductAttachment.serializeList(updatedList)
                if (myStore != null) {
                    val updatedStore = myStore.copy(productAttachmentsJson = json)
                    viewModel.saveStore(updatedStore)
                }
            },
            mode = "MANAGEMENT",
            themeColors = themeColors
        )

        // Restore Account reminder / button
        Card(
            colors = CardDefaults.cardColors(containerColor = Color(0xFF0F172A)),
            border = BorderStroke(1.dp, themeColors.accent.copy(alpha = 0.4f)),
            shape = RoundedCornerShape(12.dp),
            modifier = Modifier.fillMaxWidth()
        ) {
            Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                Text("🔄 حماية واسترجاع حسابك والدردشات", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = themeColors.accent)
                Text(
                    text = "حسابك مشفر سحابياً برقم هاتفك. في حال قمت بمسح بيانات الهاتف أو الانتقال لهاتف جديد، يمكنك الضغط على 'استرجاع الحساب' لاسترداد كافة حجوزاتك ومحادثاتك فوراً.",
                    fontSize = 10.sp,
                    color = Color.LightGray
                )
                Button(
                    onClick = { showRestoreDialog = true },
                    colors = ButtonDefaults.buttonColors(containerColor = themeColors.accent.copy(alpha = 0.15f)),
                    border = BorderStroke(1.dp, themeColors.accent),
                    shape = RoundedCornerShape(8.dp),
                    modifier = Modifier.fillMaxWidth().height(36.dp),
                    contentPadding = PaddingValues(0.dp)
                ) {
                    Text("🔓 اضغط لاسترجاع حساب سابق الآن", color = themeColors.accent, fontSize = 10.sp, fontWeight = FontWeight.Bold)
                }
            }
        }

        // Bookings section
        Text("📅 طلبات وحجوزات الخدمة الخاصة بك:", fontSize = 13.sp, fontWeight = FontWeight.Bold, color = themeColors.accent)
        val myBookings = remember(bookings, currentUserPhone) { bookings.filter { it.customerPhone == currentUserPhone } }
        
        if (myBookings.isEmpty()) {
            Card(
                colors = CardDefaults.cardColors(containerColor = themeColors.surface),
                shape = RoundedCornerShape(12.dp),
                modifier = Modifier.fillMaxWidth()
            ) {
                Text(
                    "لم تقم بإجراء أي حجوزات بعد. بمجرد قيامك بالحجز، ستظهر تفاصيل الحجز هنا مباشرة للتحكم ومتابعة الفنيين.",
                    fontSize = 11.sp,
                    color = themeColors.textSecondary,
                    modifier = Modifier.padding(16.dp),
                    textAlign = TextAlign.Center
                )
            }
        } else {
            myBookings.forEach { b ->
                Card(
                    colors = CardDefaults.cardColors(containerColor = themeColors.surface),
                    shape = RoundedCornerShape(12.dp),
                    modifier = Modifier.fillMaxWidth(),
                    border = BorderStroke(1.dp, Color.Gray.copy(alpha = 0.2f))
                ) {
                    Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
                            Text("الطلب #${b.bookingNumber}", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = themeColors.accent)
                            
                            val statusText = when(b.status) {
                                "PENDING" -> "⏳ قيد الانتظار"
                                "APPROVED" -> "✅ مقبول"
                                "COMPLETED" -> "🎯 مكتمل"
                                "CANCELLED" -> "❌ ملغي"
                                else -> b.status
                            }
                            val statusColor = when(b.status) {
                                "PENDING" -> Color(0xFFFFB703)
                                "APPROVED" -> Color(0xFF2EC4B6)
                                "COMPLETED" -> Color(0xFF00B4D8)
                                "CANCELLED" -> Color(0xFFE63946)
                                else -> Color.White
                            }
                            Text(
                                text = statusText,
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = statusColor,
                                modifier = Modifier
                                    .background(statusColor.copy(alpha = 0.15f), RoundedCornerShape(4.dp))
                                    .padding(horizontal = 6.dp, vertical = 2.dp)
                            )
                        }

                        Text("الفني المطلوب: ${b.providerName}", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color.White)
                        Text("الخدمة والمشكلة: ${b.serviceType}", fontSize = 10.sp, color = themeColors.textSecondary)
                        Text("الموعد المقترح: ${b.dateString} - ${b.timeString}", fontSize = 10.sp, color = themeColors.textSecondary)

                        if (b.status == "PENDING" || b.status == "APPROVED") {
                            // Direct Chat with provider button
                            Button(
                                onClick = {
                                    showDirectSupportChat = true
                                },
                                colors = ButtonDefaults.buttonColors(containerColor = themeColors.accent),
                                shape = RoundedCornerShape(6.dp),
                                modifier = Modifier.fillMaxWidth().height(32.dp),
                                contentPadding = PaddingValues(0.dp)
                            ) {
                                Text("💬 مراسلة فورية سريعة بخصوص هذا الطلب", color = Color.Black, fontSize = 10.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(10.dp))
        Divider(color = themeColors.accent.copy(alpha = 0.2f))

        // Options to register as technician or add store anyway
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            Button(
                onClick = onShowRegistrationFormsAnyway,
                colors = ButtonDefaults.buttonColors(containerColor = themeColors.surface),
                border = BorderStroke(1.dp, themeColors.accent.copy(alpha = 0.5f)),
                shape = RoundedCornerShape(8.dp),
                modifier = Modifier.weight(1f).height(36.dp),
                contentPadding = PaddingValues(0.dp)
            ) {
                Text("💼 الانضمام أو إضافة متجر", color = themeColors.accent, fontSize = 9.sp, fontWeight = FontWeight.Bold)
            }
            Button(
                onClick = {
                    viewModel.logout(context)
                },
                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF7F1D1D).copy(alpha = 0.3f)),
                border = BorderStroke(1.dp, Color.Red),
                shape = RoundedCornerShape(8.dp),
                modifier = Modifier.weight(1f).height(36.dp),
                contentPadding = PaddingValues(0.dp)
            ) {
                Text("🚪 تسجيل الخروج / تبديل الحساب", color = Color.Red, fontSize = 9.sp, fontWeight = FontWeight.Bold)
            }
        }
    }

    if (showDirectSupportChat) {
        ChatPanelDialogView(viewModel = viewModel, themeColors = themeColors, onDismiss = { showDirectSupportChat = false })
    }

    // Direct Restore account Dialog
    if (showRestoreDialog) {
        var restorePhone by remember { mutableStateOf("") }
        var restorePass by remember { mutableStateOf("") }
        var isRestoring by remember { mutableStateOf(false) }

        Dialog(onDismissRequest = { showRestoreDialog = false }) {
            Card(
                colors = CardDefaults.cardColors(containerColor = themeColors.surface),
                shape = RoundedCornerShape(16.dp),
                border = BorderStroke(1.dp, themeColors.accent),
                modifier = Modifier.fillMaxWidth().padding(16.dp)
            ) {
                Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    Text("🔓 استرجاع حساب سابق موحد", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = themeColors.accent)
                    
                    OutlinedTextField(
                        value = restorePhone,
                        onValueChange = { restorePhone = it },
                        label = { Text("رقم هاتفك اليمني المكون من 9 أرقام") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                        modifier = Modifier.fillMaxWidth(),
                        colors = OutlinedTextFieldDefaults.colors(focusedTextColor = Color.White, unfocusedTextColor = Color.White)
                    )
                    OutlinedTextField(
                        value = restorePass,
                        onValueChange = { restorePass = it },
                        label = { Text("كلمة المرور السرية للحساب") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password),
                        modifier = Modifier.fillMaxWidth(),
                        colors = OutlinedTextFieldDefaults.colors(focusedTextColor = Color.White, unfocusedTextColor = Color.White)
                    )

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Button(
                            onClick = {
                                val cleanPhone = restorePhone.trim().replace(" ", "")
                                val cleanPass = restorePass.trim()
                                if (cleanPhone.length == 9 && cleanPass.isNotEmpty()) {
                                    isRestoring = true
                                    viewModel.restoreGuestUser(
                                        context = context,
                                        phone = cleanPhone,
                                        password = cleanPass,
                                        onResult = { success, msg ->
                                            isRestoring = false
                                            if (success) {
                                                showRestoreDialog = false
                                            }
                                            android.widget.Toast.makeText(context, msg, android.widget.Toast.LENGTH_LONG).show()
                                        }
                                    )
                                } else {
                                    android.widget.Toast.makeText(context, "❌ يرجى تعبئة كافة الحقول بشكل صحيح!", android.widget.Toast.LENGTH_SHORT).show()
                                }
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = themeColors.primary),
                            modifier = Modifier.weight(1f)
                        ) {
                            Text(if (isRestoring) "جاري الاسترجاع..." else "تأكيد واسترجاع", fontSize = 11.sp, color = Color.White)
                        }
                        TextButton(onClick = { showRestoreDialog = false }) {
                            Text("إلغاء", color = Color.White, fontSize = 11.sp)
                        }
                    }
                }
            }
        }
    }
}

// ------ Provider Registration Form Layout ------
fun Color.luminance() : Float {
    return (0.2126f * this.red + 0.7152f * this.green + 0.0722f * this.blue)
}

@Composable
fun ProviderRegisterFormLayout(
    viewModel: MainViewModel,
    themeColors: VisualThemePalette,
    regType: String,
    sectionId: String,
    onRegTypeChange: (String) -> Unit
) {
    val categories by viewModel.categories.collectAsState()
    val settingsState by viewModel.settings.collectAsState()
    val context = LocalContext.current
    val currentUserName by viewModel.currentUserName.collectAsState()
    val currentUserPhone by viewModel.currentUserPhone.collectAsState()
    val currentUserResidence by viewModel.currentUserResidence.collectAsState()
    val currentUserId by viewModel.currentUserId.collectAsState()
    val bookings by viewModel.bookings.collectAsState()
    val pendingProviders by viewModel.pendingProviders.collectAsState()
    val providers by viewModel.providers.collectAsState()
    val stores by viewModel.stores.collectAsState()
    val properties by viewModel.properties.collectAsState()

    val reqs = remember(settingsState.registrationRequirements) {
        settingsState.registrationRequirements.split(",").map { req ->
            val parts = req.split("|")
            val reqName = parts.getOrNull(0)?.trim() ?: req.trim()
            val isMandatory = parts.getOrNull(1)?.trim()?.lowercase() != "optional"
            reqName to isMandatory
        }
    }

    val isNameMandatory = reqs.firstOrNull { it.first.contains("الاسم") }?.second ?: true
    val isPhoneMandatory = reqs.firstOrNull { it.first.contains("الهاتف") }?.second ?: true
    val isCatMandatory = reqs.firstOrNull { it.first.contains("القسم") || it.first.contains("الصيانة") }?.second ?: true
    val isAreaMandatory = reqs.firstOrNull { it.first.contains("المدينة") || it.first.contains("المحافظة") || it.first.contains("السكن") }?.second ?: true
    val isNeighbourMandatory = reqs.firstOrNull { it.first.contains("الحي") || it.first.contains("الشارع") }?.second ?: false
