                    if (isOwner) {
                        isAuthorized = true
                        viewModel.authenticateAdmin(context, "OWNER", rememberMe)
                    } else if (isAdmin) {
                        isAuthorized = true
                        viewModel.authenticateAdmin(context, "ADMIN", rememberMe)
