    // Dynamic booking target dialog shown when clicked from map card
    bookingProviderTargetOnMap?.let { p ->
        val currentUserName by viewModel.currentUserName.collectAsState()
        val currentUserPhone by viewModel.currentUserPhone.collectAsState()
        val currentUserResidence by viewModel.currentUserResidence.collectAsState()

        var clientNameInput by remember { mutableStateOf(currentUserName) }
        var clientPhoneInput by remember { mutableStateOf(currentUserPhone) }
        var clientResidenceInput by remember { mutableStateOf(currentUserResidence) }
        var detailsInput by remember { mutableStateOf("") }
        var preferredTimeInput by remember { mutableStateOf("غداً الساعة 4:00 مساءً") }
        var pinCodeInput by remember { mutableStateOf("") }
        
        var formSubmittedOnce by remember { mutableStateOf(false) }
        var missingFields by remember { mutableStateOf<List<String>>(emptyList()) }
        
        AlertDialog(
            onDismissRequest = { bookingProviderTargetOnMap = null },
            containerColor = Color(0xFF1E293B),
            title = { Text("🗓️ طلب موعد حجز فوري: ${p.name}", color = Color(0xFFFFD700), fontWeight = FontWeight.Bold, fontSize = 14.sp) },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth().verticalScroll(rememberScrollState())) {
                    Text("الرجاء إدخال كافة بياناتك السكنية والاتصال لإرسال الطلب وحفظ حسابك:", color = Color.White, fontSize = 11.sp)
                    
                    if (formSubmittedOnce && missingFields.isNotEmpty()) {
                        Card(
                            colors = CardDefaults.cardColors(containerColor = Color(0xFFEF4444).copy(alpha = 0.15f)),
                            border = BorderStroke(1.dp, Color(0xFFEF4444)),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(modifier = Modifier.padding(10.dp)) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Text("⚠️", fontSize = 14.sp)
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text("يرجى إكمال وتصحيح الحقول المطلوبة:", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFFEF4444))
                                }
                                Spacer(modifier = Modifier.height(4.dp))
                                missingFields.forEach { field ->
                                    Text("• $field", fontSize = 10.sp, color = Color.White)
                                }
                            }
                        }
                    }

                    OutlinedTextField(
                        value = clientNameInput,
                        onValueChange = { clientNameInput = it },
                        label = { Text("الاسم الثلاثي بالكامل (مطلوب) *") },
                        modifier = Modifier.fillMaxWidth(),
                        isError = formSubmittedOnce && clientNameInput.trim().isEmpty(),
                        colors = OutlinedTextFieldDefaults.colors(focusedTextColor = Color.White, unfocusedTextColor = Color.White)
                    )
                    OutlinedTextField(
                        value = clientPhoneInput,
                        onValueChange = { clientPhoneInput = it },
                        label = { Text("رقم الهاتف اليمني المكون من 9 أرقام (مطلوب) *") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                        modifier = Modifier.fillMaxWidth(),
                        isError = formSubmittedOnce && (clientPhoneInput.trim().isEmpty() || !clientPhoneInput.trim().replace(" ", "").replace("+", "").let { p ->
                            p.length == 9 && (p.startsWith("77") || p.startsWith("73") || p.startsWith("71") || p.startsWith("70") || p.startsWith("78"))
                        }),
                        colors = OutlinedTextFieldDefaults.colors(focusedTextColor = Color.White, unfocusedTextColor = Color.White)
                    )
                    OutlinedTextField(
                        value = clientResidenceInput,
                        onValueChange = { clientResidenceInput = it },
                        label = { Text("الحي والشارع ومنطقة السكن (مطلوب) *") },
                        modifier = Modifier.fillMaxWidth(),
                        isError = formSubmittedOnce && clientResidenceInput.trim().isEmpty(),
                        colors = OutlinedTextFieldDefaults.colors(focusedTextColor = Color.White, unfocusedTextColor = Color.White)
                    )
                    OutlinedTextField(
                        value = detailsInput,
                        onValueChange = { detailsInput = it },
                        label = { Text("تفاصيل ومعلومات مشكلة الصيانة (مطلوب) *") },
                        modifier = Modifier.fillMaxWidth(),
                        isError = formSubmittedOnce && detailsInput.trim().isEmpty(),
                        colors = OutlinedTextFieldDefaults.colors(focusedTextColor = Color.White, unfocusedTextColor = Color.White)
                    )
                    OutlinedTextField(
                        value = preferredTimeInput,
                        onValueChange = { preferredTimeInput = it },
                        label = { Text("الوقت المقترح") },
                        modifier = Modifier.fillMaxWidth(),
                        colors = OutlinedTextFieldDefaults.colors(focusedTextColor = Color.White, unfocusedTextColor = Color.White)
                    )
                    OutlinedTextField(
                        value = pinCodeInput,
                        onValueChange = { pinCodeInput = it },
                        label = { Text("🔑 كلمة مرور سرية لحفظ وتأمين الحجز (مطلوب) *") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password),
                        modifier = Modifier.fillMaxWidth(),
                        isError = formSubmittedOnce && pinCodeInput.trim().isEmpty(),
                        colors = OutlinedTextFieldDefaults.colors(focusedTextColor = Color.White, unfocusedTextColor = Color.White)
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        val cleanName = clientNameInput.trim()
                        val cleanPhone = clientPhoneInput.trim().replace(" ", "").replace("+", "")
                        val cleanResidence = clientResidenceInput.trim()
                        val cleanDetails = detailsInput.trim()
                        val cleanPin = pinCodeInput.trim()

                        // Validations and detailed toast error reporting
                        val isValidYemeniPhone = cleanPhone.length == 9 && (
                            cleanPhone.startsWith("77") || 
                            cleanPhone.startsWith("73") || 
                            cleanPhone.startsWith("71") || 
                            cleanPhone.startsWith("70") || 
                            cleanPhone.startsWith("78")
                        )

                        val missing = mutableListOf<String>()
                        if (cleanName.isEmpty()) missing.add("الاسم الثلاثي بالكامل")
                        if (cleanPhone.isEmpty()) {
                            missing.add("رقم الهاتف")
                        } else if (!isValidYemeniPhone) {
                            missing.add("رقم الهاتف اليمني غير صحيح (يجب أن يتكون من 9 أرقام ويبدأ بـ 77، 73، 71، 70، 78)")
                        }
                        if (cleanResidence.isEmpty()) missing.add("الحي والشارع ومكان السكن")
                        if (cleanDetails.isEmpty()) missing.add("تفاصيل ومعلومات المشكلة")
                        if (cleanPin.isEmpty()) missing.add("كلمة المرور السرية للحجز")

                        if (missing.isNotEmpty()) {
                            formSubmittedOnce = true
                            missingFields = missing
                            Toast.makeText(context, "⚠️ هناك حقول مطلوبة أو غير صحيحة!", Toast.LENGTH_LONG).show()
                        } else {
                            formSubmittedOnce = false
                            missingFields = emptyList()
                            viewModel.addBooking(
                                name = cleanName,
                                phone = cleanPhone,
                                area = cleanResidence,
                                serviceType = "رادار الخريطة - $cleanDetails",
                                providerId = p.id,
                                providerName = p.name,
                                dateString = "2026-06-21",
                                timeString = preferredTimeInput.trim(),
                                customPassword = cleanPin,
                                pinCode = cleanPin
                            )
                            viewModel.registerGuestUser(
                                context = context,
                                name = cleanName,
                                phone = cleanPhone,
                                residence = cleanResidence,
                                password = cleanPin
                            )
                            bookingProviderTargetOnMap = null
                            selectedProviderForMap = null
                            Toast.makeText(context, "تم إرسال طلب الحجز بنجاح بالرقم المرجعي الموحد! 🚀", Toast.LENGTH_LONG).show()
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = themeColors.primary)
                ) {
                    Text("تأكيد وتأمين الطلب")
                }
            },
            dismissButton = {
                TextButton(onClick = { bookingProviderTargetOnMap = null }) {
                    Text("إلغاء", color = Color.White)
                }
            }
        )
    }
}

@Composable
fun JoinRequestStatusScreen(viewModel: MainViewModel, themeColors: VisualThemePalette) {
    val context = LocalContext.current
    val joinPhone by viewModel.joinRequestPhone.collectAsState()
    val pendingProviders by viewModel.pendingProviders.collectAsState()
    val providers by viewModel.providers.collectAsState()
    val notifications by viewModel.notifications.collectAsState()
    val bookings by viewModel.bookings.collectAsState()
    val chatChannels by viewModel.chatChannels.collectAsState()

    var activeProviderChatChannel by remember { mutableStateOf<com.example.data.ChatChannelEntity?>(null) }
    var replyInputText by remember { mutableStateOf("") }

    LaunchedEffect(chatChannels, activeProviderChatChannel?.id) {
        activeProviderChatChannel?.id?.let { activeId ->
            val latestCh = chatChannels.find { it.id == activeId }
            if (latestCh != null && latestCh.messages.size != activeProviderChatChannel?.messages?.size) {
                activeProviderChatChannel = latestCh
            }
        }
    }

    val matchingPending = pendingProviders.find { it.phone == joinPhone }
    val matchingApproved = providers.find { it.phone == joinPhone }
    
    val stores by viewModel.stores.collectAsState()
    val properties by viewModel.properties.collectAsState()
    val ratings by viewModel.ratings.collectAsState()

    val matchingStore = remember(stores, joinPhone) {
        stores.find { it.ownerId.trim() == joinPhone.trim() && joinPhone.isNotEmpty() && !it.isDeleted }
    }
    val matchingProperty = remember(properties, joinPhone) {
        properties.find { it.phone.trim() == joinPhone.trim() && joinPhone.isNotEmpty() && !it.isDeleted }
    }

    if (matchingStore != null && matchingStore.isActive) {
        val accType = if (matchingStore.sectionId.contains("restaurant") || matchingStore.name.contains("مطعم") || matchingStore.description.contains("أكل") || matchingStore.description.contains("وجبة")) "RESTAURANT" else if (matchingStore.sectionId.contains("medical") || matchingStore.name.contains("عيادة") || matchingStore.name.contains("طبي")) "MEDICAL" else "STORE"
        com.example.ui.UnifiedBusinessProfileDashboard(accountType = accType, providerId = matchingStore.id, viewModel = viewModel, themeColors = themeColors)
        return
    }
    if (matchingProperty != null && matchingProperty.isActive) {
        com.example.ui.UnifiedBusinessProfileDashboard(accountType = "REAL_ESTATE", providerId = matchingProperty.id, viewModel = viewModel, themeColors = themeColors)
        return
    }
    if (matchingApproved != null) {
        com.example.ui.UnifiedBusinessProfileDashboard(accountType = "TECHNICIAN", providerId = matchingApproved.id, viewModel = viewModel, themeColors = themeColors)
        return
    }

    // Look for rejection notification
    val rejectionNotif = notifications.find { 
        it.targetValue == joinPhone && (it.title.contains("رفض") || it.message.contains("رفض") || it.title.contains("تنويه"))
    }

    LaunchedEffect(rejectionNotif, matchingApproved, matchingPending) {
        if (rejectionNotif != null && matchingApproved == null && matchingPending == null) {
            android.widget.Toast.makeText(context, "❌ تم تنبيهك: ${rejectionNotif.message}", android.widget.Toast.LENGTH_LONG).show()
            viewModel.cancelOrResetJoinRequest(context)
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp)
            .verticalScroll(rememberScrollState()),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center
    ) {
        Card(
            modifier = Modifier
                .fillMaxWidth()
                .padding(vertical = 12.dp),
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(containerColor = themeColors.surface),
            elevation = CardDefaults.cardElevation(defaultElevation = 6.dp),
            border = BorderStroke(
                width = 1.5.dp,
                color = when {
                    matchingApproved != null || matchingStore != null || matchingProperty != null -> Color(0xFF10B981)
                    rejectionNotif != null -> Color(0xFFEF4444)
                    else -> Color(0xFFF59E0B)
                }
            )
        ) {
            Column(
                modifier = Modifier.padding(20.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                val categories by viewModel.categories.collectAsState()
                when {
                    matchingStore != null -> {
                        StoreOwnerDashboardLayout(store = matchingStore, viewModel = viewModel, themeColors = themeColors, ratings = ratings)
                    }
                    matchingProperty != null -> {
                        PropertyOwnerDashboardLayout(property = matchingProperty, viewModel = viewModel, themeColors = themeColors, ratings = ratings)
                    }
                    matchingApproved != null -> {
                        // Accepted (Image 2 design style + Full Interactive Provider Dashboard)
                        Box(
                            modifier = Modifier
                                .size(56.dp)
                                .background(Color(0xFF10B981).copy(alpha = 0.2f), CircleShape),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = "✅",
                                fontSize = 28.sp
                            )
                        }
                        
                        Text(
                            text = "🎉 تم تفعيل حسابك كفني معتمد!",
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color(0xFF10B981),
                            textAlign = TextAlign.Center
                        )
                        
                        Text(
                            text = "مرحباً بك يا غالي! حسابك نشط الآن في دليل كل خدمات اليمن ومتاح لجميع العملاء للتواصل والحجز المباشر.",
                            fontSize = 11.sp,
                            color = Color.White.copy(alpha = 0.85f),
                            textAlign = TextAlign.Center,
                            lineHeight = 16.sp
                        )
                        
                        Divider(color = Color.White.copy(alpha = 0.1f), thickness = 1.dp)
                        
                        // 1. Profile Summary Card
                        Card(
                            colors = CardDefaults.cardColors(containerColor = Color(0xFF111C15)),
                            border = BorderStroke(1.dp, Color(0xFF10B981).copy(alpha = 0.3f)),
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Row(
                                modifier = Modifier.padding(12.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(44.dp)
                                        .background(Color(0xFF10B981), CircleShape),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text("👷", fontSize = 20.sp)
                                }
                                Spacer(modifier = Modifier.width(10.dp))
                                Column {
                                    Text(
                                        text = matchingApproved.name,
                                        fontSize = 13.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color.White
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Text("💼", fontSize = 10.sp)
                                        Spacer(modifier = Modifier.width(4.dp))
                                        val catName = if (matchingApproved.categoryId == "other" && matchingApproved.customCategoryName.isNotEmpty()) matchingApproved.customCategoryName else (categories.find { it.id == matchingApproved.categoryId }?.name ?: "صيانة فنية")
                                        Text(catName, fontSize = 10.sp, color = Color.LightGray)
                                    }
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Text("📍", fontSize = 10.sp)
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Text("${matchingApproved.area} - ${matchingApproved.localNeighborhood}", fontSize = 10.sp, color = Color.LightGray)
                                    }
                                }
                            }
                        }

                        // 2. Active Status Toggle Button
                        Button(
                            onClick = {
                                viewModel.updateProviderEntity(matchingApproved.copy(isAvailable = !matchingApproved.isAvailable))
                            },
                            colors = ButtonDefaults.buttonColors(
                                containerColor = if (matchingApproved.isAvailable) Color(0xFFEF4444).copy(alpha = 0.15f) else Color(0xFF10B981).copy(alpha = 0.15f)
                            ),
                            border = BorderStroke(1.dp, if (matchingApproved.isAvailable) Color(0xFFEF4444) else Color(0xFF10B981)),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier.fillMaxWidth().height(38.dp)
                        ) {
                            Text(
                                text = if (matchingApproved.isAvailable) "🔴 تغيير حالتك الحالية إلى: مشغول مؤقتاً" else "🟢 تغيير حالتك الحالية إلى: متاح للعمل فوراً",
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = if (matchingApproved.isAvailable) Color(0xFFEF4444) else Color(0xFF10B981)
                            )
                        }

                        // 3. Private Bookings Section
                        val myBookings = bookings.filter { it.providerId == matchingApproved.id }
                        Text("📅 طلبات الحجز والعمل الموجهة لك:", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = themeColors.accent, modifier = Modifier.align(Alignment.Start))
                        if (myBookings.isEmpty()) {
                            Card(
                                colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.03f)),
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Box(modifier = Modifier.padding(14.dp), contentAlignment = Alignment.Center) {
                                    Text("📭 لا توجد طلبات حجز موجهة لك حالياً.", fontSize = 10.sp, color = Color.Gray)
                                }
                            }
                        } else {
                            myBookings.forEach { b ->
                                Card(
                                    colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.05f)),
                                    border = BorderStroke(0.5.dp, Color.White.copy(alpha = 0.1f)),
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    Column(modifier = Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                            Text("العميل: ${b.customerName}", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color.White)
                                            Text(
                                                text = when(b.status) {
                                                    "PENDING" -> "⏳ بانتظار تأكيدك"
                                                    "APPROVED", "IN_PROGRESS" -> "🟢 مقبول وجاري التنفيذ"
                                                    "REJECTED" -> "❌ مرفوض"
                                                    "COMPLETED" -> "✅ مكتمل"
                                                    else -> b.status
                                                },
                                                fontSize = 9.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = when(b.status) {
                                                    "PENDING" -> Color.Yellow
                                                    "APPROVED", "IN_PROGRESS", "COMPLETED" -> Color.Green
                                                    else -> Color.Red
                                                }
                                            )
                                        }
                                        Text("📞 هاتف العميل للتواصل: ${b.customerPhone}", fontSize = 10.sp, color = themeColors.accent)
                                        Text("📍 موقع ومحافظة العميل: ${b.customerArea}", fontSize = 10.sp, color = Color.LightGray)
                                        Text("🔧 الخدمة المطلوبة: ${b.serviceType}", fontSize = 10.sp, color = Color.LightGray)
                                        Text("⏰ موعد الزيارة: ${b.dateString} - ${b.timeString}", fontSize = 10.sp, color = Color.LightGray)
                                        
                                        if (b.status == "PENDING") {
                                            Row(modifier = Modifier.fillMaxWidth().padding(top = 4.dp), horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                                Button(
                                                    onClick = { viewModel.updateBookingStatus(b.id, "IN_PROGRESS") },
                                                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF10B981)),
                                                    modifier = Modifier.weight(1f).height(28.dp),
                                                    contentPadding = PaddingValues(0.dp)
                                                ) {
                                                    Text("موافقة وقبول العمل ✅", fontSize = 9.sp, color = Color.Black, fontWeight = FontWeight.Bold)
                                                }
                                                Button(
                                                    onClick = { viewModel.updateBookingStatus(b.id, "REJECTED", "اعتذر الفني لإنشغاله") },
                                                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFEF4444)),
                                                    modifier = Modifier.weight(1f).height(28.dp),
                                                    contentPadding = PaddingValues(0.dp)
                                                ) {
                                                    Text("اعتذار ورفض العمل ❌", fontSize = 9.sp, color = Color.White)
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        // 4. Conversations/Chats section
                        val myChats = chatChannels.filter { it.id.contains("chat_p_${matchingApproved.id}_") || it.id.contains("_u_${matchingApproved.id}") }
                        Text("💬 محادثات العملاء المباشرة معك:", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = themeColors.accent, modifier = Modifier.align(Alignment.Start))
                        if (myChats.isEmpty()) {
                            Card(
                                colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.03f)),
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Box(modifier = Modifier.padding(14.dp), contentAlignment = Alignment.Center) {
                                    Text("📭 لا توجد محادثات نشطة مع عملاء حالياً.", fontSize = 10.sp, color = Color.Gray)
                                }
                            }
                        } else {
                            myChats.forEach { ch ->
                                Card(
                                    colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.05f)),
                                    modifier = Modifier.fillMaxWidth().clickable {
                                        activeProviderChatChannel = ch
                                    }
                                ) {
                                    Row(modifier = Modifier.padding(10.dp), verticalAlignment = Alignment.CenterVertically) {
                                        Text("💬", fontSize = 15.sp)
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Column(modifier = Modifier.weight(1f)) {
                                            Text(ch.userName, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color.White)
                                            Text(ch.lastMessage, fontSize = 10.sp, color = Color.LightGray, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                        }
                                        Text("◀️", fontSize = 10.sp, color = themeColors.accent)
                                    }
                                }
                            }
                        }

                        // 5. Notifications Section
                        val myNotifs = notifications.filter { it.targetValue == matchingApproved.phone || it.targetType == "ALL" }
                        Text("🔔 الإشعارات والتعميمات الإدارية الموجهة إليك:", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = themeColors.accent, modifier = Modifier.align(Alignment.Start))
                        if (myNotifs.isEmpty()) {
                            Card(
                                colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.03f)),
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Box(modifier = Modifier.padding(14.dp), contentAlignment = Alignment.Center) {
                                    Text("📭 لا توجد إشعارات إدارية جديدة.", fontSize = 10.sp, color = Color.Gray)
                                }
                            }
                        } else {
                            myNotifs.take(4).forEach { notif ->
                                Card(
                                    colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.05f)),
                                    border = BorderStroke(1.dp, Color.White.copy(alpha = 0.1f)),
                                    modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp)
                                ) {
                                    Column(modifier = Modifier.padding(12.dp)) {
                                        Text(notif.title, fontSize = 12.sp, fontWeight = FontWeight.Bold, color = themeColors.accent)
                                        Spacer(modifier = Modifier.height(4.dp))
                                        Text(notif.message, fontSize = 11.sp, color = Color.LightGray, lineHeight = 16.sp)
                                        
                                        if (notif.customerPhone.isNotEmpty()) {
                                            Spacer(modifier = Modifier.height(8.dp))
                                            Divider(color = Color.White.copy(alpha = 0.1f), thickness = 0.5.dp)
                                            Spacer(modifier = Modifier.height(8.dp))
                                            
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                                            ) {
                                                // Call Button
                                                Button(
                                                    onClick = {
                                                        val intent = Intent(Intent.ACTION_DIAL, Uri.parse("tel:${notif.customerPhone}"))
                                                        context.startActivity(intent)
                                                    },
                                                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF10B981)),
                                                    shape = RoundedCornerShape(6.dp),
                                                    modifier = Modifier.weight(1f),
                                                    contentPadding = PaddingValues(vertical = 4.dp, horizontal = 8.dp)
                                                ) {
                                                    Text("📞 اتصال مباشر", fontSize = 10.sp, color = Color.White, fontWeight = FontWeight.Bold)
                                                }
                                                
                                                // Chat Button
                                                Button(
                                                    onClick = {
                                                        val sorted = listOf(matchingApproved.id, notif.customerPhone).sorted()
                                                        val newTargetId = "chat_${sorted[0]}_${sorted[1]}"
                                                        val oldTargetId = "chat_p_${matchingApproved.id}_u_${notif.customerPhone}"
                                                        val existingChannel = chatChannels.find { it.id == newTargetId } ?: chatChannels.find { it.id == oldTargetId }
                                                        val finalId = existingChannel?.id ?: newTargetId
                                                        
                                                        viewModel.getOrCreateChatChannel(
                                                            matchingApproved.id,
                                                            matchingApproved.name,
                                                            notif.customerPhone,
                                                            notif.customerName
                                                        )
                                                        
                                                        activeProviderChatChannel = existingChannel ?: com.example.data.ChatChannelEntity(
                                                            id = finalId,
                                                            userName = notif.customerName.ifEmpty { "عميل جديد" },
                                                            lastMessage = "",
                                                            messages = emptyList()
                                                        )
                                                    },
                                                    colors = ButtonDefaults.buttonColors(containerColor = themeColors.accent),
                                                    shape = RoundedCornerShape(6.dp),
                                                    modifier = Modifier.weight(1f),
                                                    contentPadding = PaddingValues(vertical = 4.dp, horizontal = 8.dp)
                                                ) {
                                                    Text("💬 مراسلة فورية", fontSize = 10.sp, color = Color.Black, fontWeight = FontWeight.Bold)
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        // Local Chat Dialog Overlay for Provider
                        activeProviderChatChannel?.let { ch ->
                            Dialog(onDismissRequest = { activeProviderChatChannel = null }) {
                                Card(
                                    colors = CardDefaults.cardColors(containerColor = Color(0xFF0F172A)),
                                    border = BorderStroke(1.dp, themeColors.accent),
                                    modifier = Modifier.padding(12.dp).fillMaxWidth()
                                ) {
                                    Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                                        Text("💬 محادثة العميل: ${ch.userName}", fontSize = 13.sp, fontWeight = FontWeight.Bold, color = themeColors.accent)
                                        
                                        Box(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .height(180.dp)
                                                .background(Color.Black.copy(alpha = 0.4f), RoundedCornerShape(8.dp))
                                                .padding(8.dp)
                                        ) {
                                            LazyColumn(modifier = Modifier.fillMaxSize(), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                                items(ch.messages) { msg ->
                                                    val isMe = msg.senderId == matchingApproved.id
                                                    val alignment = if (isMe) Alignment.End else Alignment.Start
                                                    val bubbleBg = if (isMe) themeColors.primary else Color.Gray.copy(alpha = 0.3f)
                                                    Column(horizontalAlignment = alignment, modifier = Modifier.fillMaxWidth()) {
                                                        Box(
                                                            modifier = Modifier
                                                                .clip(RoundedCornerShape(8.dp))
                                                                .background(bubbleBg)
                                                                .padding(horizontal = 10.dp, vertical = 6.dp)
                                                        ) {
                                                            Text(msg.message, fontSize = 10.sp, color = Color.White)
                                                        }
                                                        val formattedDate = remember(msg.timestamp) {
                                                            try {
                                                                java.text.SimpleDateFormat("yyyy/MM/dd hh:mm a", java.util.Locale("ar")).format(java.util.Date(msg.timestamp))
                                                            } catch (e: Exception) { "" }
                                                        }
                                                        Row(
                                                            verticalAlignment = Alignment.CenterVertically,
                                                            horizontalArrangement = Arrangement.spacedBy(4.dp)
                                                        ) {
                                                            Text(msg.senderName, fontSize = 8.sp, color = themeColors.textSecondary)
                                                            Text("• $formattedDate", fontSize = 8.sp, color = Color.Gray)
                                                            if (isMe) {
                                                                val statusIcon = when (msg.status) {
                                                                    "READ" -> "✓✓ تمت القراءة"
                                                                    "DELIVERED" -> "✓✓ تم التسليم"
                                                                    else -> "✓ مرسل"
                                                                }
                                                                val statusColor = when (msg.status) {
                                                                    "READ" -> Color(0xFF10B981)
                                                                    "DELIVERED" -> themeColors.accent
                                                                    else -> Color.Gray
                                                                }
                                                                Text(statusIcon, fontSize = 8.sp, color = statusColor, fontWeight = FontWeight.Bold)
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }

                                        OutlinedTextField(
                                            value = replyInputText,
                                            onValueChange = { replyInputText = it },
                                            placeholder = { Text("اكتب ردك هنا...") },
                                            modifier = Modifier.fillMaxWidth(),
                                            colors = OutlinedTextFieldDefaults.colors(focusedTextColor = Color.White, unfocusedTextColor = Color.White)
                                        )

                                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                            Button(
                                                onClick = {
                                                    if (replyInputText.trim().isNotEmpty()) {
                                                        viewModel.replyToChatChannel(ch.id, matchingApproved.id, replyInputText.trim(), matchingApproved.name)
                                                        // Refresh chat locally
                                                        val updatedMsg = com.example.data.ChatMessageEntity(
                                                            id = UUID.randomUUID().toString(),
                                                            senderId = matchingApproved.id,
                                                            message = replyInputText.trim(),
                                                            timestamp = System.currentTimeMillis(),
                                                            senderName = matchingApproved.name
                                                        )
                                                        activeProviderChatChannel = ch.copy(
                                                            messages = ch.messages + updatedMsg,
                                                            lastMessage = replyInputText.trim(),
                                                            timestamp = System.currentTimeMillis()
                                                        )
                                                        replyInputText = ""
                                                    }
                                                },
                                                colors = ButtonDefaults.buttonColors(containerColor = themeColors.accent),
                                                modifier = Modifier.weight(1f)
                                            ) {
                                                Text("إرسال الرد السريع ⚡", color = Color.Black, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    matchingPending != null -> {
                        // Pending approval screen
                        Box(
                            modifier = Modifier
                                .size(56.dp)
                                .background(Color(0xFFF59E0B).copy(alpha = 0.2f), CircleShape),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(text = "⏳", fontSize = 28.sp)
                        }

                        Text(
                            text = "⏳ طلب انضمامك قيد المراجعة حالياً",
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color(0xFFF59E0B),
                            textAlign = TextAlign.Center
                        )

                        Text(
                            text = "أهلاً بك يا غالي! تم إرسال طلبك بنجاح وهو قيد المراجعة والتدقيق الإداري الآن من قبل الإدارة. نسعد بانضمامك وسنبلغك فور التنشيط والموافقة لتتمكن من استقبال الحجوزات والدردشة مباشرة!",
                            fontSize = 11.sp,
                            color = Color.White.copy(alpha = 0.85f),
                            textAlign = TextAlign.Center,
                            lineHeight = 16.sp
                        )

                        HorizontalDivider(color = Color.White.copy(alpha = 0.1f), thickness = 1.dp)

                        Card(
                            colors = CardDefaults.cardColors(containerColor = Color(0xFF2D2214)),
                            border = BorderStroke(1.dp, Color(0xFFF59E0B).copy(alpha = 0.3f)),
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                Text("📋 تفاصيل الطلب المقدم:", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color(0xFFF59E0B))
                                Text("• الاسم الثلاثي: ${matchingPending.name}", fontSize = 11.sp, color = Color.White, fontWeight = FontWeight.Bold)
                                Text("• رقم الهاتف: ${matchingPending.phone}", fontSize = 11.sp, color = Color.White)
                                val catName = if (matchingPending.categoryId == "other" && matchingPending.customCategoryName.isNotEmpty()) matchingPending.customCategoryName else (categories.find { it.id == matchingPending.categoryId }?.name ?: "صيانة عامة")
                                Text("• القسم والتخصص: $catName", fontSize = 11.sp, color = Color.White)
                                Text("• منطقة الخدمة: ${matchingPending.area}", fontSize = 11.sp, color = Color.White)
                                if (matchingPending.localNeighborhood.isNotEmpty()) {
                                    Text("• الحي/الشارع التفصيلي: ${matchingPending.localNeighborhood}", fontSize = 11.sp, color = Color.White)
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(12.dp))

                        Button(
                            onClick = {
                                viewModel.cancelOrResetJoinRequest(context)
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color.Gray),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier.fillMaxWidth().height(38.dp)
                        ) {
                            Text("❌ إلغاء الطلب والعودة للرئيسية", color = Color.White, fontSize = 11.sp)
                        }
                    }
                    else -> {
                        // Fallback state
                        Box(
                            modifier = Modifier
                                .size(56.dp)
                                .background(Color.Gray.copy(alpha = 0.2f), CircleShape),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(text = "ℹ️", fontSize = 28.sp)
                        }

                        Text(
                            text = "لم يتم العثور على طلب نشط",
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color.White,
                            textAlign = TextAlign.Center
                        )

                        Text(
                            text = "يرجى تقديم طلب انضمام جديد للتمتع بكافة الميزات والتحكم ببياناتك وحجوزاتك كفني معتمد.",
                            fontSize = 11.sp,
                            color = Color.LightGray,
                            textAlign = TextAlign.Center
                        )

                        Spacer(modifier = Modifier.height(12.dp))

                        Button(
                            onClick = {
                                viewModel.cancelOrResetJoinRequest(context)
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = themeColors.accent),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier.fillMaxWidth().height(38.dp)
                        ) {
                            Text("📝 العودة لشاشة التسجيل", color = Color.Black, fontWeight = FontWeight.Bold, fontSize = 11.sp)
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun InAppVoiceCallDialog(
    callerName: String,
    callerRole: String,
    onDismiss: () -> Unit,
    themeColors: VisualThemePalette
) {
    val context = LocalContext.current
    var callState by remember { mutableStateOf("RINGING") } // RINGING, CONNECTED, UNANSWERED
    var isMuted by remember { mutableStateOf(false) }
    var isSpeakerOn by remember { mutableStateOf(true) }
    var callSeconds by remember { mutableStateOf(0) }
    var ringingSeconds by remember { mutableStateOf(0) }

    LaunchedEffect(callState) {
        if (callState == "RINGING") {
            ringingSeconds = 0
            while (callState == "RINGING" && ringingSeconds < 8) {
                kotlinx.coroutines.delay(1000)
                ringingSeconds++
            }
            if (callState == "RINGING" && ringingSeconds >= 8) {
                callState = "UNANSWERED"
            }
        } else if (callState == "CONNECTED") {
            callSeconds = 0
            while (callState == "CONNECTED") {
                kotlinx.coroutines.delay(1000)
                callSeconds++
            }
        }
    }

    androidx.compose.ui.window.Dialog(
        onDismissRequest = onDismiss,
        properties = androidx.compose.ui.window.DialogProperties(
            usePlatformDefaultWidth = false,
            decorFitsSystemWindows = true
        )
    ) {
        Surface(
            color = Color(0xFF0F172A),
            shape = RoundedCornerShape(20.dp),
            border = BorderStroke(2.dp, themeColors.accent),
            modifier = Modifier
                .fillMaxWidth(0.92f)
                .padding(16.dp)
        ) {
            Column(
                modifier = Modifier.padding(24.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                Text(
                    text = "🎙️ مكالمة صوتية عالية الجودة (HD)",
                    color = themeColors.accent,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold
                )

                Box(
                    modifier = Modifier
                        .size(90.dp)
                        .background(themeColors.primary.copy(alpha = 0.3f), CircleShape)
                        .border(2.dp, themeColors.accent, CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Text("👤", fontSize = 42.sp)
                }

                Text(
                    text = callerName,
                    color = Color.White,
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold
                )

                Text(
                    text = callerRole,
                    color = Color.LightGray,
                    fontSize = 12.sp
                )

                when (callState) {
                    "RINGING" -> {
                        Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(6.dp)) {
                            Text("📲 جاري الاتصال والرنين... 🔔 (${8 - ringingSeconds}ث)", color = Color.Yellow, fontSize = 13.sp, fontWeight = FontWeight.Bold)
                            Text("في انتظار قبول وإجابة $callerName...", color = Color.Gray, fontSize = 11.sp)
                            
                            Spacer(modifier = Modifier.height(4.dp))
                            Button(
                                onClick = {
                                    callState = "CONNECTED"
                                    Toast.makeText(context, "🟢 تم قبول المكالمة وبدء التواصل المباشر", Toast.LENGTH_SHORT).show()
                                },
                                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF10B981)),
                                shape = RoundedCornerShape(10.dp)
                            ) {
                                Text("🟢 إجابة المكالمة (محاكاة التوصيل)", fontSize = 11.sp, color = Color.White, fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                    "UNANSWERED" -> {
                        Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(6.dp)) {
                            Text("⚠️ المشترك لا يجيب حالياً أو أن هاتفه مغلق/خارج التغطية.", color = Color.Red, fontSize = 12.sp, fontWeight = FontWeight.Bold, textAlign = androidx.compose.ui.text.style.TextAlign.Center)
                            Text("يرجى إرسال رسالة نصية في المحادثة أو المحاولة لاحقاً.", color = Color.LightGray, fontSize = 11.sp, textAlign = androidx.compose.ui.text.style.TextAlign.Center)
                            
                            Spacer(modifier = Modifier.height(4.dp))
                            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                Button(
                                    onClick = { callState = "RINGING" },
                                    colors = ButtonDefaults.buttonColors(containerColor = themeColors.accent)
                                ) {
                                    Text("إعادة المحاولة 🔄", color = Color.Black, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                }
                                Button(
                                    onClick = onDismiss,
                                    colors = ButtonDefaults.buttonColors(containerColor = Color.DarkGray)
                                ) {
                                    Text("إغلاق ❌", color = Color.White, fontSize = 11.sp)
                                }
                            }
                        }
                    }
                    "CONNECTED" -> {
                        val mins = callSeconds / 60
                        val secs = callSeconds % 60
                        val timeStr = String.format("%02d:%02d", mins, secs)
                        Text("🟢 متصل الآن ($timeStr) - جودة صوتية HD", color = Color.Green, fontSize = 13.sp, fontWeight = FontWeight.Bold)
                    }
                }

                if (callState == "CONNECTED") {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(top = 12.dp),
                        horizontalArrangement = Arrangement.SpaceEvenly,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        IconButton(
                            onClick = {
                                isMuted = !isMuted
                                if (isMuted) {
                                    Toast.makeText(context, "🔇 تم كتم الميكروفون", Toast.LENGTH_SHORT).show()
                                } else {
                                    Toast.makeText(context, "🎙️ الميكروفون يعمل الآن", Toast.LENGTH_SHORT).show()
                                }
                            },
                            modifier = Modifier
                                .background(if (isMuted) Color.Red.copy(alpha = 0.3f) else Color.White.copy(alpha = 0.15f), CircleShape)
                                .size(48.dp)
                        ) {
                            Text(if (isMuted) "🔇" else "🎙️", fontSize = 20.sp)
                        }

                        Button(
                            onClick = onDismiss,
                            colors = ButtonDefaults.buttonColors(containerColor = Color.Red),
                            shape = CircleShape,
                            modifier = Modifier.size(60.dp),
                            contentPadding = PaddingValues(0.dp)
                        ) {
                            Text("📞", fontSize = 24.sp, color = Color.White)
                        }

                        IconButton(
                            onClick = {
                                isSpeakerOn = !isSpeakerOn
                                if (isSpeakerOn) {
                                    Toast.makeText(context, "🔊 تم تشغيل مكبر الصوت الخارجي", Toast.LENGTH_SHORT).show()
                                } else {
                                    Toast.makeText(context, "🔈 تم إيقاف مكبر الصوت (السماعة الداخلية)", Toast.LENGTH_SHORT).show()
                                }
                            },
                            modifier = Modifier
                                .background(if (isSpeakerOn) themeColors.accent.copy(alpha = 0.3f) else Color.White.copy(alpha = 0.15f), CircleShape)
                                .size(48.dp)
                        ) {
                            Text(if (isSpeakerOn) "🔊" else "🔈", fontSize = 20.sp)
                        }
                    }
                } else if (callState == "RINGING") {
                    Button(
                        onClick = onDismiss,
                        colors = ButtonDefaults.buttonColors(containerColor = Color.Red),
                        shape = CircleShape,
                        modifier = Modifier.size(54.dp),
                        contentPadding = PaddingValues(0.dp)
                    ) {
                        Text("📞", fontSize = 22.sp, color = Color.White)
                    }
                }
            }
        }
    }
}

@Composable
fun AllConversationsDialogView(
    viewModel: MainViewModel,
    themeColors: VisualThemePalette,
    initialSelectedChannelId: String? = null,
    onReadTrigger: () -> Unit = {},
    onDismiss: () -> Unit
) {
    val context = LocalContext.current
    val currentUserId by viewModel.currentUserId.collectAsState()
    val currentUserPhone by viewModel.currentUserPhone.collectAsState()
    val currentUserName by viewModel.currentUserName.collectAsState()
    val chatChannels by viewModel.chatChannels.collectAsState()
    val providers by viewModel.providers.collectAsState()
    val settingsState by viewModel.settings.collectAsState()

    val myProvider = providers.find { it.phone == currentUserPhone }

    val myChannels = remember(chatChannels, currentUserId, currentUserPhone, myProvider) {
        chatChannels.filter { ch ->
            ch.id == "support_$currentUserId" ||
            ch.id.contains(currentUserId) ||
            (currentUserPhone.isNotEmpty() && ch.id.contains(currentUserPhone)) ||
            (myProvider != null && (ch.id.contains("chat_p_${myProvider.id}_") || ch.id.contains("_u_${myProvider.id}"))) ||
            currentUserId == "admin" || currentUserId.startsWith("super_")
        }
    }

    var selectedChannelId by remember { mutableStateOf<String?>(initialSelectedChannelId) }
    val selectedChannel = remember(chatChannels, selectedChannelId) {
        chatChannels.find { it.id == selectedChannelId }
    }
    var replyText by remember { mutableStateOf("") }
    val sharedPrefs = remember(context) { context.getSharedPreferences("yemen_service_prefs", android.content.Context.MODE_PRIVATE) }

    LaunchedEffect(selectedChannelId, chatChannels) {
        selectedChannelId?.let { chId ->
            val ch = chatChannels.find { it.id == chId }
            val lastMsg = ch?.messages?.lastOrNull()
            if (lastMsg != null) {
                val isMe = lastMsg.senderId == currentUserId || (myProvider != null && lastMsg.senderId == myProvider.id)
                if (!isMe) {
                    sharedPrefs.edit().putLong("chat_read_$chId", System.currentTimeMillis()).apply()
                    onReadTrigger()
                }
            }
        }
    }

    // Auto mark messages as read when opening channel
    LaunchedEffect(selectedChannelId) {
        selectedChannelId?.let { chId ->
            viewModel.markChatMessagesAsRead(chId, currentUserId)
        }
    }

    // Media attachment pickers
    val photoPickerLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.PickVisualMedia()
    ) { uri ->
        if (uri != null) {
            val ch = selectedChannel
            if (ch != null) {
                val currentImagesCount = ch.messages.count { it.imageUrl.isNotEmpty() && !it.imageUrl.contains("video_") }
                if (currentImagesCount >= settingsState.maxImagesPerChat) {
                    Toast.makeText(context, "⚠️ تجاوزت الحد الأقصى للصور (${settingsState.maxImagesPerChat})", Toast.LENGTH_LONG).show()
                } else {
                    val senderName = currentUserName.ifEmpty { myProvider?.name ?: "مستخدم" }
                    val senderId = myProvider?.id ?: currentUserId
                    Toast.makeText(context, "⏳ جاري رفع الصورة والمزامنة...", Toast.LENGTH_SHORT).show()
                    viewModel.uploadChatMediaToStorage(uri, isVideo = false) { uploadedUrl ->
                        viewModel.replyToChatChannel(ch.id, senderId, "[صورة مرفقة]", senderName, imageUrl = uploadedUrl)
                        onReadTrigger()
                        Toast.makeText(context, "📷 تم إرسال الصورة بنجاح!", Toast.LENGTH_SHORT).show()
                    }
                }
            }
        }
    }

    val videoPickerLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.PickVisualMedia()
    ) { uri ->
        if (uri != null) {
            val ch = selectedChannel
            if (ch != null) {
                val currentVideosCount = ch.messages.count { it.imageUrl.contains("video_") || it.message == "[فيديو مرفق]" }
                if (currentVideosCount >= settingsState.maxVideosPerChat) {
                    Toast.makeText(context, "⚠️ تجاوزت الحد الأقصى للفيديوهات (${settingsState.maxVideosPerChat})", Toast.LENGTH_LONG).show()
                } else {
                    val senderName = currentUserName.ifEmpty { myProvider?.name ?: "مستخدم" }
                    val senderId = myProvider?.id ?: currentUserId
                    Toast.makeText(context, "⏳ جاري رفع الفيديو والمزامنة...", Toast.LENGTH_SHORT).show()
                    viewModel.uploadChatMediaToStorage(uri, isVideo = true) { uploadedUrl ->
                        viewModel.replyToChatChannel(ch.id, senderId, "[فيديو مرفق]", senderName, imageUrl = if (uploadedUrl.startsWith("video_")) uploadedUrl else "video_$uploadedUrl")
                        onReadTrigger()
                        Toast.makeText(context, "🎥 تم إرسال الفيديو بنجاح!", Toast.LENGTH_SHORT).show()
                    }
                }
            }
        }
    }

    // Checking if the chat is disabled by Admin
    val chatDisabledReason = remember(settingsState, currentUserId, myProvider, selectedChannelId) {
        val chId = selectedChannelId ?: ""
        val isCustomerProviderChat = chId.startsWith("chat_p_") || (chId.startsWith("chat_") && !chId.startsWith("support_"))
        if (settingsState.disableChatAll) {
            "⚠️ الدردشة متوقفة حالياً للصيانة بقرار الإدارة: " + settingsState.chatDisabledAnnouncement
        } else if (settingsState.disableChatUsers && myProvider == null && currentUserId != "admin" && !currentUserId.startsWith("super_")) {
            "⚠️ تم تعطيل الدردشة للعملاء والزائرين حالياً."
        } else if (settingsState.disableChatProviders && myProvider != null) {
            "⚠️ تم تعطيل الدردشة للفنيين ومزودي الخدمة حالياً."
        } else if (isCustomerProviderChat && !settingsState.allowChatUserToProvider) {
            "⚠️ تم إيقاف الدردشة المباشرة بين العملاء والفنيين."
        } else {
            null
        }
    }

    // Dynamic Header Title
    val titleText = remember(selectedChannelId, chatChannels, providers, currentUserId, myProvider, settingsState) {
        val ch = chatChannels.find { it.id == selectedChannelId }
        if (ch == null) {
            "💬 كل محادثاتك المباشرة"
        } else {
            if (ch.id.startsWith("support_")) {
                "💬 الدعم الفني المباشر والسرع"
            } else if (ch.id.startsWith("chat_p_") || (ch.id.startsWith("chat_") && !ch.id.startsWith("support_"))) {
                val providerId = if (ch.id.startsWith("chat_p_")) {
                    ch.id.substringAfter("chat_p_").substringBefore("_u_")
                } else {
                    val parts = ch.id.removePrefix("chat_").split("_")
                    if (parts.size == 2) {
                        if (providers.any { it.id == parts[0] }) parts[0] else parts[1]
                    } else ""
                }
                val providerObj = providers.find { it.id == providerId }
                if (myProvider != null && myProvider.id == providerId) {
                    val rawCustomerName = ch.customerName.ifEmpty { ch.userName.substringAfter("مع ").ifEmpty { "عميل" } }
                    val custPhone = ch.customerPhone.ifEmpty { currentUserPhone }
                    if (settingsState.showUserIdInsteadOfNameInChat) {
                        val custId = ch.customerId.ifEmpty { if (custPhone.isNotEmpty()) "USR-${custPhone.takeLast(6)}" else "USR-CLIENT" }
                        "👤 العميل: $custId"
                    } else {
                        "👤 العميل: $rawCustomerName ${if (custPhone.isNotEmpty()) "($custPhone)" else ""}"
                    }
                } else {
                    val pName = providerObj?.name ?: ch.userName.substringAfter("دردشة: ").substringBefore(" مع")
                    "👷 الفني: $pName"
                }
            } else {
                ch.userName
            }
        }
    }

    androidx.compose.ui.window.Dialog(
        onDismissRequest = onDismiss,
        properties = androidx.compose.ui.window.DialogProperties(
            usePlatformDefaultWidth = false,
            decorFitsSystemWindows = true
        )
    ) {
        Surface(
            color = Color(0xFF0F172A),
            shape = RoundedCornerShape(16.dp),
            border = BorderStroke(1.5.dp, themeColors.accent),
            modifier = Modifier
                .fillMaxSize()
                .padding(horizontal = 8.dp, vertical = 20.dp)
                .systemBarsPadding()
                .imePadding()
        ) {
            Column(modifier = Modifier.padding(14.dp)) {
                var activeVoiceCall by remember { mutableStateOf<Pair<String, String>?>(null) }

                if (activeVoiceCall != null) {
                    InAppVoiceCallDialog(
                        callerName = activeVoiceCall!!.first,
                        callerRole = activeVoiceCall!!.second,
                        onDismiss = { activeVoiceCall = null },
                        themeColors = themeColors
                    )
                }

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = titleText,
                        fontSize = 15.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color.White,
                        modifier = Modifier.weight(1f, fill = false)
                    )
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                        if (selectedChannelId != null && !settingsState.disableVoiceCalls) {
                            Button(
                                onClick = {
                                    val cleanTitle = titleText.removePrefix("👤 العميل: ").removePrefix("👷 الفني: ").removePrefix("💬 ")
                                    activeVoiceCall = Pair(cleanTitle, "مكالمة صوتية مباشرة HD")
                                },
                                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF10B981)),
                                contentPadding = PaddingValues(horizontal = 8.dp, vertical = 2.dp),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Text("🎙️ اتصال", color = Color.White, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                        IconButton(onClick = { if (selectedChannelId != null) selectedChannelId = null else onDismiss() }, modifier = Modifier.size(28.dp)) {
                            Text(if (selectedChannelId != null) "🔙" else "❌", color = Color.White, fontSize = 14.sp)
                        }
                    }
                }

                Divider(color = Color.White.copy(alpha = 0.15f), modifier = Modifier.padding(vertical = 8.dp))

                if (selectedChannelId == null) {
                    if (myChannels.isEmpty()) {
                        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                            Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                Text("💬", fontSize = 36.sp)
                                Text("لا توجد محادثات نشطة حالياً.", fontSize = 12.sp, color = Color.Gray)
                                Button(
                                    onClick = {
                                        onDismiss()
                                        viewModel.navigateTo("USER_BROWSE")
                                    },
                                    colors = ButtonDefaults.buttonColors(containerColor = themeColors.accent)
                                ) {
                                    Text("ابدأ محادثة مع الدعم الفني", color = Color.Black, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                }
                            }
                        }
                    } else {
                        LazyColumn(modifier = Modifier.fillMaxSize(), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            item {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.End
                                ) {
                                    Button(
                                        onClick = {
                                            myChannels.forEach { ch ->
                                                viewModel.deleteChatChannel(ch.id)
                                            }
                                            viewModel.triggerNotification("🗑️ تم حذف جميع المحادثات بنجاح.")
                                            onReadTrigger()
                                        },
                                        colors = ButtonDefaults.buttonColors(containerColor = Color.Red.copy(alpha = 0.8f)),
                                        contentPadding = PaddingValues(horizontal = 12.dp, vertical = 4.dp),
                                        shape = RoundedCornerShape(6.dp)
                                    ) {
                                        Text("حذف جميع المحادثات 🗑️", color = Color.White, fontSize = 10.sp, fontWeight = FontWeight.Bold)
                                    }
                                }
                            }

                            items(myChannels) { ch ->
                                val displayItemTitle = remember(ch, providers, currentUserId, myProvider) {
                                    if (ch.id.startsWith("support_")) {
                                        "💬 الدعم الفني المباشر"
                                    } else if (ch.id.startsWith("chat_p_") || (ch.id.startsWith("chat_") && !ch.id.startsWith("support_"))) {
                                        val providerId = if (ch.id.startsWith("chat_p_")) {
                                            ch.id.substringAfter("chat_p_").substringBefore("_u_")
                                        } else {
                                            val parts = ch.id.removePrefix("chat_").split("_")
                                            if (parts.size == 2) {
                                                if (providers.any { it.id == parts[0] }) parts[0] else parts[1]
                                            } else ""
                                        }
                                        val providerObj = providers.find { it.id == providerId }
                                        if (myProvider != null && myProvider.id == providerId) {
                                            val customerNamePart = ch.userName.substringAfter("مع ").ifEmpty { "عميل" }
                                            "👤 العميل: $customerNamePart"
                                        } else {
                                            val pName = providerObj?.name ?: ch.userName.substringAfter("دردشة: ").substringBefore(" مع")
                                            "👷 الفني: $pName"
                                        }
                                    } else {
                                        ch.userName
                                    }
                                }

                                val unreadThisChat = remember(ch, chatChannels) {
                                    val lastMsg = ch.messages.lastOrNull()
                                    if (lastMsg == null) {
                                        false
                                    } else {
                                        val isMe = lastMsg.senderId == currentUserId || (myProvider != null && lastMsg.senderId == myProvider.id)
                                        val readTime = sharedPrefs.getLong("chat_read_${ch.id}", 0L)
                                        !isMe && lastMsg.timestamp > readTime
                                    }
                                }

                                Card(
                                    colors = CardDefaults.cardColors(containerColor = if (unreadThisChat) themeColors.accent.copy(alpha = 0.1f) else Color.White.copy(alpha = 0.05f)),
                                    border = BorderStroke(if (unreadThisChat) 1.dp else 0.5.dp, if (unreadThisChat) themeColors.accent else Color.White.copy(alpha = 0.1f)),
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    Row(
                                        modifier = Modifier.padding(12.dp).fillMaxWidth(),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Row(
                                            modifier = Modifier.weight(1f).clickable { selectedChannelId = ch.id },
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text("💬", fontSize = 18.sp)
                                            Spacer(modifier = Modifier.width(10.dp))
                                            Column {
                                                Text(displayItemTitle, fontSize = 12.sp, fontWeight = FontWeight.Bold, color = if (unreadThisChat) themeColors.accent else Color.White)
                                                Text(ch.lastMessage, fontSize = 10.sp, color = if (unreadThisChat) themeColors.accent.copy(alpha = 0.8f) else Color.LightGray, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                            }
                                        }

                                        IconButton(
                                            onClick = {
                                                viewModel.deleteChatChannel(ch.id)
                                                onReadTrigger()
                                            },
                                            modifier = Modifier.size(28.dp)
                                        ) {
                                            Text("🗑️", fontSize = 14.sp)
                                        }

                                        Spacer(modifier = Modifier.width(4.dp))

                                        Text(
                                            text = "◀️",
                                            fontSize = 11.sp,
                                            color = themeColors.accent,
                                            modifier = Modifier.clickable { selectedChannelId = ch.id }
                                        )
                                    }
                                }
                            }
                        }
                    }
                } else {
                    val ch = selectedChannel
                    if (ch == null) {
                        selectedChannelId = null
                    } else {
                        Column(modifier = Modifier.fillMaxSize()) {
                            Box(
                                modifier = Modifier
                                    .weight(1f)
                                    .fillMaxWidth()
                                    .background(Color.Black.copy(alpha = 0.4f), RoundedCornerShape(12.dp))
                                    .padding(8.dp)
                            ) {
                                LazyColumn(modifier = Modifier.fillMaxSize(), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                    items(ch.messages) { msg ->
                                        val isMe = msg.senderId == currentUserId || msg.senderId == myProvider?.id
                                        val alignment = if (isMe) Alignment.End else Alignment.Start
                                        val bubbleBg = if (isMe) themeColors.primary else Color(0xFF1E293B)
                                        
                                        val timeFormatted = remember(msg.timestamp) {
                                            if (msg.timestamp > 0) {
                                                try {
                                                    java.text.SimpleDateFormat("hh:mm a", java.util.Locale("ar")).format(java.util.Date(msg.timestamp))
                                                } catch(e: Exception) { "" }
                                            } else ""
                                        }

                                        Column(horizontalAlignment = alignment, modifier = Modifier.fillMaxWidth().padding(horizontal = 4.dp)) {
                                            Box(
                                                modifier = Modifier
                                                    .clip(RoundedCornerShape(12.dp))
                                                    .background(bubbleBg)
                                                    .padding(horizontal = 12.dp, vertical = 8.dp)
                                            ) {
                                                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                                    if (msg.imageUrl.startsWith("video_")) {
                                                        Box(
                                                            modifier = Modifier
                                                                .size(150.dp)
                                                                .clip(RoundedCornerShape(8.dp))
                                                                .background(Color.Black)
                                                                .clickable {
                                                                    Toast.makeText(context, "▶️ جاري تشغيل الفيديو المرفق...", Toast.LENGTH_SHORT).show()
                                                                },
                                                            contentAlignment = Alignment.Center
                                                        ) {
                                                            Icon(
                                                                imageVector = Icons.Default.PlayArrow,
                                                                contentDescription = "تشغيل الفيديو",
                                                                tint = Color.White,
                                                                modifier = Modifier.size(48.dp)
                                                            )
                                                            Text(
                                                                "تشغيل الفيديو 🎥",
                                                                fontSize = 10.sp,
                                                                color = Color.White,
                                                                modifier = Modifier.align(Alignment.BottomCenter).padding(bottom = 8.dp)
                                                            )
                                                        }
                                                    } else if (msg.imageUrl.isNotEmpty()) {
                                                        AsyncImage(
                                                            model = msg.imageUrl,
                                                            contentDescription = "صورة مرفقة",
                                                            modifier = Modifier.size(150.dp).clip(RoundedCornerShape(8.dp))
                                                        )
                                                    }
                                                    if (msg.message.isNotEmpty() && msg.message != "[صورة مرفقة]" && msg.message != "[فيديو مرفق]") {
                                                        Text(msg.message, fontSize = 13.sp, color = Color.White, lineHeight = 19.sp)
                                                    }

                                                    Row(
                                                        verticalAlignment = Alignment.CenterVertically,
                                                        horizontalArrangement = Arrangement.End,
                                                        modifier = Modifier.align(Alignment.End)
                                                    ) {
                                                        if (timeFormatted.isNotEmpty()) {
                                                            Text(timeFormatted, fontSize = 9.sp, color = Color.White.copy(alpha = 0.7f))
                                                        }
                                                        if (isMe) {
                                                            Spacer(modifier = Modifier.width(4.dp))
                                                            val (statusIcon, statusColor) = when (msg.status) {
                                                                "READ" -> "✔✔" to Color(0xFF38BDF8)
                                                                "DELIVERED" -> "✔✔" to Color.LightGray
                                                                else -> "✔" to Color.LightGray
                                                            }
                                                            Text(statusIcon, fontSize = 10.sp, color = statusColor, fontWeight = FontWeight.Bold)
                                                        }
                                                    }
                                                }
                                            }
                                            Text(msg.senderName, fontSize = 9.sp, color = themeColors.textSecondary, modifier = Modifier.padding(horizontal = 4.dp, vertical = 2.dp))
                                        }
                                    }
                                }
                            }

                            Spacer(modifier = Modifier.height(8.dp))

                            if (replyText.isNotEmpty()) {
                                Text(
                                    text = "💬 جاري الكتابة...",
                                    fontSize = 10.sp,
                                    color = themeColors.accent,
                                    modifier = Modifier.padding(start = 8.dp, bottom = 4.dp),
                                    fontWeight = FontWeight.Bold
                                )
                            }

                            if (chatDisabledReason != null) {
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .background(Color.Red.copy(alpha = 0.15f), RoundedCornerShape(8.dp))
                                        .padding(8.dp)
                                ) {
                                    Text(chatDisabledReason, fontSize = 11.sp, color = Color.Red, fontWeight = FontWeight.Bold, textAlign = TextAlign.Center, modifier = Modifier.fillMaxWidth())
                                }
                            } else {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    verticalAlignment = Alignment.Bottom,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    // Image attachment trigger
                                    if (settingsState.allowSendImages) {
                                        IconButton(
                                            onClick = {
                                                photoPickerLauncher.launch(
                                                    androidx.activity.result.PickVisualMediaRequest(
                                                        ActivityResultContracts.PickVisualMedia.ImageOnly
                                                    )
                                                )
                                            },
                                            modifier = Modifier.size(40.dp)
                                        ) {
                                            Text("📷", fontSize = 18.sp)
                                        }
                                    }

                                    // Video attachment trigger
                                    if (settingsState.allowSendVideos) {
                                        IconButton(
                                            onClick = {
                                                videoPickerLauncher.launch(
                                                    androidx.activity.result.PickVisualMediaRequest(
                                                        ActivityResultContracts.PickVisualMedia.VideoOnly
                                                    )
                                                )
                                            },
                                            modifier = Modifier.size(40.dp)
                                        ) {
                                            Text("🎥", fontSize = 18.sp)
                                        }
                                    }

                                    OutlinedTextField(
                                        value = replyText,
                                        onValueChange = { replyText = it },
                                        placeholder = { Text("اكتب رسالتك...", fontSize = 13.sp, color = Color.Gray) },
                                        modifier = Modifier.weight(1f),
                                        minLines = 1,
                                        maxLines = 4,
                                        textStyle = androidx.compose.ui.text.TextStyle(fontSize = 13.sp, color = Color.White, lineHeight = 18.sp),
                                        colors = OutlinedTextFieldDefaults.colors(
                                            focusedTextColor = Color.White,
                                            unfocusedTextColor = Color.White,
                                            focusedBorderColor = themeColors.accent,
                                            unfocusedBorderColor = Color.White.copy(alpha = 0.3f),
                                            focusedContainerColor = Color(0xFF1E293B),
                                            unfocusedContainerColor = Color(0xFF1E293B)
                                        ),
                                        shape = RoundedCornerShape(12.dp)
                                    )

                                    Button(
                                        onClick = {
                                            if (replyText.trim().isNotEmpty()) {
                                                val senderName = currentUserName.ifEmpty { myProvider?.name ?: "مستخدم" }
                                                val senderId = myProvider?.id ?: currentUserId
                                                viewModel.replyToChatChannel(ch.id, senderId, replyText.trim(), senderName)
                                                
                                                replyText = ""
                                                onReadTrigger()
                                            }
                                        },
                                        colors = ButtonDefaults.buttonColors(containerColor = themeColors.accent),
                                        modifier = Modifier.height(48.dp),
                                        shape = RoundedCornerShape(12.dp)
                                    ) {
                                        Text("إرسال", color = Color.Black, fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun GuestRegistrationDialog(
    viewModel: MainViewModel,
    themeColors: VisualThemePalette,
    onDismiss: () -> Unit,
    onRegisterCompleted: (String, String, String, String) -> Unit
) {
    val currentName = viewModel.currentUserName.collectAsState().value
    val currentPhone = viewModel.currentUserPhone.collectAsState().value
    val currentResidence = viewModel.currentUserResidence.collectAsState().value
    val settingsState by viewModel.settings.collectAsState()

    var isRestoreMode by remember { mutableStateOf(false) }
    var name by remember { mutableStateOf(currentName) }
    var phonePrefix by remember { mutableStateOf("+967") }
    var phoneBody by remember { mutableStateOf(if (currentPhone.startsWith("+967")) currentPhone.removePrefix("+967") else currentPhone) }
    var residence by remember { mutableStateOf(currentResidence) }
    var password by remember { mutableStateOf("") }
    
    val context = LocalContext.current

    androidx.compose.ui.window.Dialog(onDismissRequest = onDismiss) {
        Card(
            colors = CardDefaults.cardColors(containerColor = Color(0xFF0F172A)),
            shape = RoundedCornerShape(16.dp),
            modifier = Modifier
                .fillMaxWidth()
                .padding(12.dp)
                .border(2.dp, themeColors.accent, RoundedCornerShape(16.dp))
        ) {
            Column(
                modifier = Modifier
                    .padding(20.dp)
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(14.dp)
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = if (isRestoreMode) "🔓 استرجاع الحساب والبيانات" else "🔐 جدار الحماية - التحقق من الهوية",
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Bold,
                        color = themeColors.accent
                    )
                    IconButton(onClick = onDismiss, modifier = Modifier.size(24.dp)) {
                        Icon(imageVector = Icons.Default.Close, contentDescription = null, tint = Color.Red)
                    }
                }

                if (isRestoreMode) {
                    Text(
                        text = "يرجى إدخال رقم هاتفك وكلمة المرور لاسترجاع حسابك وحجوزاتك ومحادثاتك السابقة بالكامل:",
                        fontSize = 11.sp,
                        color = Color.LightGray,
                        lineHeight = 16.sp
                    )

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .clip(RoundedCornerShape(8.dp))
                                .background(Color.White.copy(alpha = 0.08f))
                                .padding(12.dp)
                        ) {
                            Text(phonePrefix, color = Color.White, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                        }

                        OutlinedTextField(
                            value = phoneBody,
                            onValueChange = { phoneBody = it },
                            placeholder = { Text("رقم الهاتف (مثلاً 777644)", fontSize = 11.sp, color = Color.Gray) },
                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                            singleLine = true,
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedTextColor = Color.White,
                                unfocusedTextColor = Color.White,
                                focusedBorderColor = themeColors.accent,
                                unfocusedBorderColor = Color.LightGray.copy(alpha = 0.5f)
                            ),
                            modifier = Modifier.weight(1f)
                        )
                    }

                    OutlinedTextField(
                        value = password,
                        onValueChange = { password = it },
                        label = { Text("كلمة المرور", fontSize = 11.sp, color = themeColors.accent) },
                        singleLine = true,
                        visualTransformation = androidx.compose.ui.text.input.PasswordVisualTransformation(),
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = Color.White,
                            unfocusedTextColor = Color.White,
                            focusedBorderColor = themeColors.accent,
                            unfocusedBorderColor = Color.LightGray.copy(alpha = 0.5f)
                        ),
                        modifier = Modifier.fillMaxWidth()
                    )

                    Button(
                        onClick = {
                            val cleanPhone = phoneBody.trim()
                            val cleanPassword = password.trim()
                            val isValidPhone = (cleanPhone.length == 9 && (
                                cleanPhone.startsWith("77") || 
                                cleanPhone.startsWith("73") || 
                                cleanPhone.startsWith("71") || 
                                cleanPhone.startsWith("70") || 
                                cleanPhone.startsWith("78")
                            )) || (cleanPhone.length == 7 && !cleanPhone.startsWith("0"))

                            if (cleanPhone.isEmpty() || cleanPassword.isEmpty()) {
                                android.widget.Toast.makeText(context, "⚠️ الرجاء إدخال رقم الهاتف وكلمة المرور!", android.widget.Toast.LENGTH_SHORT).show()
                            } else if (!isValidPhone) {
                                android.widget.Toast.makeText(context, "⚠️ رقم الهاتف غير صالح!", android.widget.Toast.LENGTH_SHORT).show()
                            } else {
                                val fullPhone = if (cleanPhone.length == 9) cleanPhone else "77$cleanPhone"
                                viewModel.restoreGuestUser(context, fullPhone, cleanPassword) { success, msg ->
                                    if (success) {
                                        onDismiss()
                                    } else {
                                        android.widget.Toast.makeText(context, msg, android.widget.Toast.LENGTH_SHORT).show()
                                    }
                                }
                            }
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = themeColors.accent),
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(44.dp),
                        shape = RoundedCornerShape(10.dp)
                    ) {
                        Text("استرجاع الحساب الآن 🔓", color = Color.Black, fontWeight = FontWeight.Bold, fontSize = 11.sp)
                    }

                    TextButton(
                        onClick = { isRestoreMode = false },
                        modifier = Modifier.align(Alignment.CenterHorizontally)
                    ) {
                        Text("إنشاء حساب جديد؟ اضغط هنا للتسجيل", color = themeColors.accent, fontSize = 11.sp)
                    }

                } else {
                    Text(
                        text = "لتفادي الحسابات والاتصالات والمحادثات الوهمية وتقليل استهلاك الموارد تماشياً مع سياسة الخصوصية بالبوابة، يرجى ملء هوية مستخدم يمني حقيقي مفعّل بالجمهورية:",
                        fontSize = 11.sp,
                        color = Color.LightGray,
                        lineHeight = 16.sp
                    )

                    OutlinedTextField(
                        value = name,
                        onValueChange = { name = it },
                        label = { Text("الاسم الثلاثي بالكامل (إجباري) *", fontSize = 11.sp, color = themeColors.accent) },
                        singleLine = true,
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = Color.White,
                            unfocusedTextColor = Color.White,
                            focusedBorderColor = themeColors.accent,
                            unfocusedBorderColor = Color.LightGray.copy(alpha = 0.5f)
                        ),
                        modifier = Modifier.fillMaxWidth()
                    )

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .clip(RoundedCornerShape(8.dp))
                                .background(Color.White.copy(alpha = 0.08f))
                                .padding(12.dp)
                        ) {
                            Text(phonePrefix, color = Color.White, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                        }

                        OutlinedTextField(
                            value = phoneBody,
                            onValueChange = { phoneBody = it },
                            placeholder = { Text("رقم الهاتف (إجباري) *", fontSize = 11.sp, color = Color.Gray) },
                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                            singleLine = true,
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedTextColor = Color.White,
                                unfocusedTextColor = Color.White,
                                focusedBorderColor = themeColors.accent,
                                unfocusedBorderColor = Color.LightGray.copy(alpha = 0.5f)
                            ),
                            modifier = Modifier.weight(1f)
                        )
                    }

                    OutlinedTextField(
                        value = residence,
                        onValueChange = { residence = it },
                        label = { Text("السكن داخل اليمن (إجباري) *", fontSize = 11.sp, color = themeColors.accent) },
                        singleLine = true,
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = Color.White,
                            unfocusedTextColor = Color.White,
                            focusedBorderColor = themeColors.accent,
                            unfocusedBorderColor = Color.LightGray.copy(alpha = 0.5f)
                        ),
                        modifier = Modifier.fillMaxWidth()
                    )

                    val isPasswordRequired = settingsState.isUserPasswordRequired
                    OutlinedTextField(
                        value = password,
                        onValueChange = { password = it },
                        label = { Text("إنشاء كلمة مرور للحساب" + (if (isPasswordRequired) " (إجباري) *" else " (اختياري)"), fontSize = 11.sp, color = themeColors.accent) },
                        singleLine = true,
                        visualTransformation = androidx.compose.ui.text.input.PasswordVisualTransformation(),
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = Color.White,
                            unfocusedTextColor = Color.White,
                            focusedBorderColor = themeColors.accent,
                            unfocusedBorderColor = Color.LightGray.copy(alpha = 0.5f)
                        ),
                        modifier = Modifier.fillMaxWidth()
                    )

                    Button(
                        onClick = {
                            val cleanName = name.trim()
                            val cleanPhone = phoneBody.trim()
                            val cleanResidence = residence.trim()
                            val cleanPassword = password.trim()

                            val isValidPhone = (cleanPhone.length == 9 && (
                                cleanPhone.startsWith("77") || 
                                cleanPhone.startsWith("73") || 
                                cleanPhone.startsWith("71") || 
                                cleanPhone.startsWith("70") || 
                                cleanPhone.startsWith("78")
                            )) || (cleanPhone.length == 7 && !cleanPhone.startsWith("0"))

                            if (cleanName.isEmpty() || cleanPhone.isEmpty() || cleanResidence.isEmpty()) {
                                android.widget.Toast.makeText(context, "⚠️ جميع الحقول ذات النجمة إجبارية!", android.widget.Toast.LENGTH_SHORT).show()
                            } else if (isPasswordRequired && cleanPassword.isEmpty()) {
                                android.widget.Toast.makeText(context, "⚠️ كلمة المرور إجبارية بقرار الإدارة!", android.widget.Toast.LENGTH_SHORT).show()
                            } else if (!isValidPhone) {
                                android.widget.Toast.makeText(context, "⚠️ رقم الهاتف غير صالح!", android.widget.Toast.LENGTH_SHORT).show()
                            } else {
                                val fullPhone = if (cleanPhone.length == 9) cleanPhone else "77$cleanPhone"
                                onRegisterCompleted(cleanName, fullPhone, cleanResidence, cleanPassword)
                            }
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = themeColors.accent),
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(44.dp),
                        shape = RoundedCornerShape(10.dp)
                    ) {
                        Text("إتمام التحقق العادل والانطلاق 🚀", color = Color.Black, fontWeight = FontWeight.Bold, fontSize = 11.sp)
                    }

                    TextButton(
                        onClick = { isRestoreMode = true },
                        modifier = Modifier.align(Alignment.CenterHorizontally)
                    ) {
                        Text("لديك حساب بالفعل؟ استرجاع الحساب الآن 🔓", color = themeColors.accent, fontSize = 11.sp)
                    }
                }
            }
        }
    }
}

@Composable
fun UserNotificationsDialogView(
    viewModel: MainViewModel,
    themeColors: VisualThemePalette,
    onDismiss: () -> Unit
) {
    val allNotifications by viewModel.notifications.collectAsState()
    val userPhone by viewModel.currentUserPhone.collectAsState()
    val adminRole by viewModel.adminRole.collectAsState()
    val readIds by viewModel.readNotificationIds.collectAsState()
    val context = androidx.compose.ui.platform.LocalContext.current

    var activeTab by remember { mutableStateOf("ALL") } // "ALL", "UNREAD", "READ"

    LaunchedEffect(Unit) {
        viewModel.loadReadNotifications(context)
    }

    val filteredNotifs = remember(allNotifications, userPhone, adminRole) {
        allNotifications.filter { notif ->
            when (notif.targetType) {
                "ALL" -> true
                "USER" -> notif.targetValue == userPhone
                "PROVIDER" -> notif.targetValue == userPhone
                "SUPERVISOR" -> adminRole != "GUEST"
                else -> true
            }
        }
    }

    val finalNotifs = remember(filteredNotifs, readIds, activeTab) {
        when (activeTab) {
            "READ" -> filteredNotifs.filter { readIds.contains(it.id) }
            "UNREAD" -> filteredNotifs.filter { !readIds.contains(it.id) }
            else -> filteredNotifs
        }
    }

    androidx.compose.ui.window.Dialog(onDismissRequest = onDismiss) {
        Card(
            colors = CardDefaults.cardColors(containerColor = Color(0xFF0F172A)),
            border = BorderStroke(2.dp, themeColors.accent),
            shape = RoundedCornerShape(16.dp),
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp)
        ) {
            Column(
                modifier = Modifier
                    .padding(16.dp)
                    .fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "🔔 مركز الإشعارات السحابية",
                        fontSize = 14.sp,
                        fontWeight = FontWeight.Bold,
                        color = themeColors.accent
                    )
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        if (filteredNotifs.isNotEmpty()) {
                            TextButton(
                                onClick = { viewModel.deleteAllNotifications() },
                                colors = ButtonDefaults.textButtonColors(contentColor = Color.Red)
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Delete,
                                        contentDescription = "مسح الكل",
                                        tint = Color.Red,
                                        modifier = Modifier.size(16.dp)
                                    )
                                    Text("مسح الكل", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color.Red)
                                }
                            }
                        }
                        IconButton(onClick = onDismiss, modifier = Modifier.size(28.dp)) {
                            Icon(imageVector = Icons.Default.Close, contentDescription = "إغلاق", tint = Color.Red)
                        }
                    }
                }

                // Modern 3-Tab Selector Row (All, Unread, Read)
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(Color(0xFF1E293B), RoundedCornerShape(8.dp))
                        .padding(3.dp),
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    val tabs = listOf(
                        Pair("ALL", "الكل 📢"),
                        Pair("UNREAD", "غير مقروءة ✉️"),
                        Pair("READ", "مقروءة ✅")
                    )
                    tabs.forEach { t ->
                        val isSel = activeTab == t.first
                        val unreadCount = if (t.first == "UNREAD") filteredNotifs.count { !readIds.contains(it.id) } else 0
                        Box(
                            modifier = Modifier
                                .weight(1f)
                                .clip(RoundedCornerShape(6.dp))
                                .background(if (isSel) themeColors.accent else Color.Transparent)
                                .clickable { activeTab = t.first }
                                .padding(vertical = 8.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                Text(
                                    text = t.second,
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (isSel) Color.Black else Color.White
                                )
                                if (unreadCount > 0) {
                                    Box(
                                        modifier = Modifier
                                            .size(16.dp)
                                            .background(Color.Red, CircleShape),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(
                                            unreadCount.toString(),
                                            color = Color.White,
                                            fontSize = 8.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                            }
                        }
                    }
                }

                Divider(color = Color.White.copy(alpha = 0.1f), thickness = 1.dp)

                if (finalNotifs.isEmpty()) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 32.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Column(horizontalAlignment = Alignment.CenterHorizontally) {
                            Text("📭", fontSize = 48.sp)
                            Spacer(modifier = Modifier.height(8.dp))
                            Text(
                                text = when(activeTab) {
                                    "READ" -> "لا توجد إشعارات مقروءة حالياً"
                                    "UNREAD" -> "لا توجد إشعارات غير مقروءة جديدة"
                                    else -> "لا توجد إشعارات نشطة حالياً"
                                },
                                color = Color.Gray,
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Medium
                            )
                        }
                    }
                } else {
                    androidx.compose.foundation.lazy.LazyColumn(
                        modifier = Modifier
                            .fillMaxWidth()
                            .heightIn(max = 350.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        items(finalNotifs, key = { it.id }) { notif ->
                            val iconText = when {
                                notif.title.contains("حجز") -> "📅"
                                notif.title.contains("دردشة") || notif.title.contains("محادثة") -> "💬"
                                notif.title.contains("طلب") -> "👷"
                                notif.title.contains("تفعيل") || notif.title.contains("قبول") -> "🎉"
                                notif.title.contains("رفض") -> "❌"
                                else -> "🔔"
                            }

                            val isUnread = !readIds.contains(notif.id)

                            Card(
                                colors = CardDefaults.cardColors(containerColor = Color(0xFF1E293B)),
                                shape = RoundedCornerShape(12.dp),
                                border = if (isUnread) BorderStroke(1.dp, Color(0xFF10B981)) else null,
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { viewModel.markNotificationAsRead(context, notif.id) }
                            ) {
                                Row(
                                    modifier = Modifier
                                        .padding(10.dp)
                                        .fillMaxWidth(),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(iconText, fontSize = 20.sp, modifier = Modifier.padding(end = 8.dp))
                                    Column(modifier = Modifier.weight(1f)) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                                        ) {
                                            Text(
                                                text = notif.title,
                                                fontSize = 12.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = themeColors.accent
                                            )
                                            if (isUnread) {
                                                Box(
                                                    modifier = Modifier
                                                        .clip(RoundedCornerShape(4.dp))
                                                        .background(Color(0xFF10B981))
                                                        .padding(horizontal = 4.dp, vertical = 1.dp)
                                                ) {
                                                    Text("جديد", color = Color.White, fontSize = 7.sp, fontWeight = FontWeight.Bold)
                                                }
                                            }
                                        }
                                        Spacer(modifier = Modifier.height(2.dp))
                                        Text(
                                            text = notif.message,
                                            fontSize = 11.sp,
                                            color = Color.White,
                                            lineHeight = 16.sp
                                        )
                                        Spacer(modifier = Modifier.height(4.dp))
                                        val formattedTime = remember(notif.timestamp) {
                                            try {
                                                val sdf = java.text.SimpleDateFormat("yyyy/MM/dd hh:mm a", java.util.Locale.getDefault())
                                                sdf.format(java.util.Date(notif.timestamp))
                                            } catch (e: Exception) {
                                                ""
                                            }
                                        }
                                        Text(
                                            text = formattedTime,
                                            fontSize = 9.sp,
                                            color = Color.Gray
                                        )
                                    }
                                    IconButton(
                                        onClick = { viewModel.deleteNotification(notif.id) },
                                        modifier = Modifier.size(32.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Delete,
                                            contentDescription = "حذف الإشعار",
                                            tint = Color.Red.copy(alpha = 0.8f),
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

fun isMoreThan8HoursBefore(dateStr: String, timeStr: String): Boolean {
    return try {
        val sdf = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.US)
        val bookingDate = sdf.parse("$dateStr $timeStr")
        if (bookingDate != null) {
            val diffMs = bookingDate.time - System.currentTimeMillis()
            val diffHours = diffMs / (1000 * 60 * 60)
            diffHours >= 8
        } else {
            true
        }
    } catch (e: Exception) {
        true
    }
}

