            Text(
                text = "الإجمالي: ${myOrders.size}",
                fontSize = 12.sp,
                color = Color.Gray
            )
        }

        if (myOrders.isEmpty()) {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .weight(1f),
                contentAlignment = Alignment.Center
            ) {
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    Text("📋", fontSize = 48.sp)
